// Τα προθέματα που φέρουν όνομα παθογόνου. Η σειρά ΕΔΩ ορίζει τα γράμματα (a, b,
// c, …) και είναι ΕΠΙΣΗΣ παγωμένη. Η ΑΝΑΖΗΤΗΣΗ γίνεται κατά ΦΘΙΝΟΝ ΜΗΚΟΣ (byLen).
const _SAG_KEYMAP_PREFIXES = [
  // οι 15 του _BUNDLE_PATHOGEN_FAMILY_PREFIXES
  'infection_hours_counter_max_', 'infection_hours_counter_',
  'nematode_dd_accumulated_', 'nematode_generation_index_', 'dh_accumulated_',
  'gdd_accumulated_', 'gdd_daily_', 'gdd_hourly_', 'fir_message_', 'fir_',
  'pei_', 'case_', 'last_spray_', 'spray_protection_end_', 'inspection_clean_',
  // δύο ακόμη οικογένειες που ο πυρήνας χτίζει αλλά η πύλη ξενιστών δεν αφορά
  'soilhist_', 'gdd_seeded_',
];
const _SAG_KEYMAP_CODE = (() => {
  // Ε2: Object.create(null) — ΧΩΡΙΣ πρωτότυπο. Με απλό {} το `p['constructor']`
  // επέστρεφε την κληρονομημένη συνάρτηση και παρήγαγε κλειδί-σκουπίδι.
  const p = Object.create(null);
  for (let i = 0; i < _SAG_KEYMAP_PATHOGENS.length; i++)
    p[_SAG_KEYMAP_PATHOGENS[i]] = (i < 10 ? '0' : '') + i;
  const pre = Object.create(null), rev = Object.create(null);
  for (let i = 0; i < _SAG_KEYMAP_PREFIXES.length; i++) {
    const L = String.fromCharCode(97 + i);
    pre[_SAG_KEYMAP_PREFIXES[i]] = L; rev[L] = _SAG_KEYMAP_PREFIXES[i];
  }
  return { p, pre, rev, byLen: _SAG_KEYMAP_PREFIXES.slice().sort((a, b) => b.length - a.length) };
})();
const _SAG_KEYMAP_RE = /^[a-z][0-9][0-9]$/;

function _sagKeyEncode(key) {
  if (typeof key !== 'string') return key;
  const B = _SAG_KEYMAP_CODE.byLen;
  for (let i = 0; i < B.length; i++) {
    const pre = B[i];
    if (key.length > pre.length && key.lastIndexOf(pre, 0) === 0) {
      const code = _SAG_KEYMAP_CODE.p[key.slice(pre.length)];
      if (code) return _SAG_KEYMAP_CODE.pre[pre] + code;
      return key;                    // πρόθεμα γνωστό, υπόλοιπο άγνωστο -> ανέπαφο
    }
  }
  return key;
}
function _sagKeyDecode(code) {
  if (typeof code !== 'string' || !_SAG_KEYMAP_RE.test(code)) return code;
  const pre = _SAG_KEYMAP_CODE.rev[code[0]];
  const name = _SAG_KEYMAP_PATHOGENS[Number(code.slice(1))];
  return (pre && name) ? pre + name : code;
}
// Ξαναχτίζει ΜΟΝΟ τα κλειδιά· οι τιμές περνούν με αναφορά, χωρίς αντιγραφή.
function _sagKeymapBox(box, fn) {
  if (!box || typeof box !== 'object' || Array.isArray(box)) return box;
  const out = {};
  for (const k in box) if (Object.prototype.hasOwnProperty.call(box, k)) {
    // Ε3: defineProperty, ΟΧΙ out[...]= — αλλιώς κλειδί «__proto__» από το σύρμα
    // ενεργοποιεί τον setter του πρωτοτύπου και ΧΑΝΕΤΑΙ αθόρυβα.
    Object.defineProperty(out, fn(k),
      { value: box[k], enumerable: true, writable: true, configurable: true });
  }
  return out;
}
function _sagKeymapBundle(obj, fn) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return obj;
  const out = {};
  for (const k in obj) if (Object.prototype.hasOwnProperty.call(obj, k)) out[k] = obj[k];
  if (out.shared && typeof out.shared === 'object') out.shared = _sagKeymapBox(out.shared, fn);
  if (Array.isArray(out.crops)) {
    out.crops = out.crops.map(c => (c && typeof c === 'object' && c.indicators
      && typeof c.indicators === 'object')
      ? Object.assign({}, c, { indicators: _sagKeymapBox(c.indicators, fn) })
      : c);
  }
  return out;
}
