// --- field_bundle compression helpers ---
function compressFieldBundle(obj) {
  // T-BUNDLE-KEYMAP-01: η κωδικοποίηση γίνεται ΕΔΩ και πουθενά αλλού.
  const json = JSON.stringify(_sagKeymapBundle(obj, _sagKeyEncode));
  const compressed = zlib.deflateRawSync(Buffer.from(json, 'utf8'));
  return compressed.toString('base64');
}
function decompressFieldBundle(b64) {
  const buf = Buffer.from(b64, 'base64');
  const decompressed = zlib.inflateRawSync(buf);
  // T-BUNDLE-KEYMAP-01: μακριά ονόματα ΠΑΝΤΑ πάνω από το σύρμα. Bundle της
  // v50.83 (μακριά κλειδιά) περνά ανέπαφο — κανένα δεν ταιριάζει σε σχήμα κωδικού.
  return _sagKeymapBundle(JSON.parse(decompressed.toString('utf8')), _sagKeyDecode);
}

