// ── T-OPS-ROUTE-02 (v50.67) · ΚΑΙ Η ΤΕΛΕΥΤΑΙΑ ΕΙΔΟΠΟΙΗΣΗ ΣΤΟΝ ΤΕΧΝΙΚΟ ──────
// Ήταν το ΜΟΝΟ σημείο που έστελνε ακόμη Notification σε ΟΛΟΥΣ τους χρήστες του
// λογαριασμού — δηλαδή και στους αγρότες, ένα μήνυμα σφάλματος JavaScript που
// δεν τους λέει τίποτα. Το T-OPS-ROUTE-01 δρομολόγησε τις τρεις λειτουργικές
// αναφορές· αυτή είχε μείνει πίσω. Στέλνεται πλέον στους ίδιους παραλήπτες
// (OPS_EMAIL -> ADMIN_ALERT_EMAIL -> sales@macc.gr), με Notification μόνο αν
// έχει οριστεί ρητά OPS_NOTIFY.
// ΠΡΟΣΟΧΗ: εδώ ΔΕΝ υπάρχει `context` — ο handler ζει έξω από τη runAnalysis.
// Το `contexttoken` και το `_sagOpsEnv` γεμίζουν μόλις ξεκινήσει η εκτέλεση·
// αν σκάσει πριν από αυτό, πέφτουμε στην παλιά συμπεριφορά (καλύτερα κάτι παρά
// σιωπή). Ο handler ΔΕΝ επιτρέπεται να πετάξει: όλα μέσα σε catch.
var _sagOpsEnv = null;
 process.on('uncaughtException', err => {
     console.log(`Uncaught Exception: ${err.message}`);
     try {
       if (_sagOpsEnv && contexttoken) {
         _sagOpsSend(_sagOpsEnv, contexttoken,
           `${analysisTitle} - Error in Analysis`,
           `${analysisTitle} - Error: ${err.message}`)
           .then(r => console.log('[T-OPS-ROUTE-02] σφάλμα -> ' + r.mail + ' email'
             + (r.notify ? ' + Notification' : '')))
           .catch(e2 => console.log('[T-OPS-ROUTE-02] αποτυχία αποστολής: ' + (e2 && e2.message)));
         return;
       }
     } catch (_e) { /* πέφτουμε στην παλιά διαδρομή */ }
     const notificationService = new Services({ token: contexttoken }).Notification;
     notificationService.send({
       title: `${analysisTitle} - Error in Analysis`,
       message: `${analysisTitle} - Error: ${err.message}`
     }).then(console.log).catch(console.log);
  });

