// T-DEADFN-01: αφαιρέθηκε η getAllUsers(). Κατέβαζε ΟΛΟΥΣ τους χρήστες του
// λογαριασμού σελίδα-σελίδα (100 ανά κλήση) σε ΚΑΘΕ εκτέλεση, και το αποτέλεσμα
// δεν το διάβαζε κανείς: ο μόνος καταναλωτής (getUsersByAccesses) ήταν ορφανός.

/* Send Push Notification */
// T-DEADFN-01: αφαιρέθηκαν οι ορφανές getFieldAccesses() και avg() — 0 αναφορές
// σε ολόκληρο το αρχείο (επαλήθευση με AST, όχι με grep). Ήταν υπολείμματα του
// παλιού μηχανισμού πρόσβασης ανά dashboard.

function getCurrentSeason(date = new Date()) {
  const month = date.getUTCMonth(); // 0 = January, 11 = December

  if (month >= 2 && month <= 4) {
    return 'Spring';  // March - May
  } else if (month >= 5 && month <= 7) {
    return 'Summer';  // June - August
  } else if (month >= 8 && month <= 10) {
    return 'Autumn';  // September - November
  } else {
    return 'Winter';  // December - February
  }
}

function getPlantAge(plantationYearStr, fieldName) {
  const currentYear = new Date().getFullYear();
  const plantationYear = parseInt(plantationYearStr, 10);

  if (isNaN(plantationYear) || plantationYear > currentYear) {
    console.log(`[${fieldName || '—'}] Άκυρο ή κενό έτος φύτευσης — θεωρείται 4 ετών (προεπιλογή). Δηλώστε το έτος φύτευσης στη φόρμα του αγρού.`);
    return 4;
  }

  return currentYear - plantationYear;
}

// ── T-PERIOD-DOY-01 (v50.54) · Ο ΧΡΟΝΟΣ ΤΗΣ ΚΑΛΛΙΕΡΓΕΙΑΣ ΕΙΝΑΙ ΚΥΚΛΙΚΟΣ ──
// ΤΟ ΣΦΑΛΜΑ: η σύγκριση γινόταν με ΑΠΟΛΥΤΕΣ ημερομηνίες. Ο αγρότης δηλώνει τις
// περιόδους ΜΙΑ φορά (π.χ. «άνθηση 11/5/2025 - 20/6/2025») και από την 1η
// Ιανουαρίου του επόμενου έτους ΚΑΜΙΑ δεν ταίριαζε ποτέ ξανά: κάθε αγρός
// έπεφτε σιωπηλά στο «vegetative». Μετρημένο: ίδια ντομάτα, περσινές περίοδοι
// -> «vegetative», φετινές -> «fruiting».
// ΤΩΡΑ: σύγκριση ΜΕΡΑΣ-ΜΗΝΑ (η φαινολογία επαναλαμβάνεται κάθε χρόνο), με
// τύλιγμα πρωτοχρονιάς για παράθυρα που περνούν τον Δεκέμβριο.
// shiftDays: μετατόπιση από τη θερμική ανωμαλία (T-SEASON-ANOM-01) — χρονιά
// που τρέχει μπροστά μπαίνει νωρίτερα στα στάδια.
function _sagMMDD(s) {
  const m = String(s || '').trim().match(/^(?:(\d{4})-)?(\d{1,2})[-\/](\d{1,2})/);
  if (!m) return null;
  const mo = Number(m[2]), d = Number(m[3]);
  if (!(mo >= 1 && mo <= 12 && d >= 1 && d <= 31)) return null;
  return mo * 100 + d;
}

function isNowInPeriod(period, shiftDays) {
  if (!period) return false;

  let startStr = null, endStr = null;
  if (typeof period === "string") {
    // Legacy string format: "Start: <iso>, End: <iso>"
    const match = period.match(/Start:\s*([\d\-T:.Z]+),\s*End:\s*([\d\-T:.Z]+)/);
    if (!match) return false;
    startStr = match[1]; endStr = match[2];
  } else if (typeof period === "object") {
    startStr = period.start; endStr = period.end;
  } else return false;
  if (!startStr || !endStr) return false;

  const s = _sagMMDD(startStr), e = _sagMMDD(endStr);
  if (s === null || e === null) return false;

  const _sh = Number(shiftDays);
  const ref = new Date();
  if (Number.isFinite(_sh) && _sh !== 0) {
    ref.setDate(ref.getDate() + Math.max(-21, Math.min(21, Math.round(_sh))));
  }
  const n = (ref.getMonth() + 1) * 100 + ref.getDate();
  return (s <= e) ? (n >= s && n <= e) : (n >= s || n <= e);
}
function groupMeasurementsByVariable(measurements) {
  const result = {};

  for (const measurement of measurements) {
    const variable = measurement.variable;

    if (!result[variable]) {
      result[variable] = [];
    }

    result[variable].push(measurement);
  }

  return result;
}


/**
 * Resolve irrigation stage for a crop using v3 per-crop periods (preferred),
 * with legacy root-level period strings as fallback.
 */
function resolveStageForCrop(crop, legacyRoot = {}, shiftDays = 0) {
  const gen = crop?.cultivation_type_general || legacyRoot?.cultivation_type_general || legacyRoot?.cultivation_type_general;
  const periods = crop?.periods || {};

  // Helper to pick a period from v3 object first, else legacy root string.
  const pick = (v3Key, legacyKey) => {
    const p = periods?.[v3Key];
    if (p && typeof p === "object") return p;
    const legacy = legacyRoot?.[legacyKey];
    if (legacy && typeof legacy === "string") return legacy;
    return null;
  };

  // Vegetables + vine crops
  if (gen === "vegetableCrops" || gen === "vineCrops" || gen === "vegetable") {
    if (isNowInPeriod(pick("transplantation", "transplantation_period"), shiftDays)) return "transplant";
    if (isNowInPeriod(pick("vegetative_growth", "vegetative_growth_period"), shiftDays)) return "vegetative";
    if (isNowInPeriod(pick("flowering", "flowering_period"), shiftDays)) return "flowering";
    if (isNowInPeriod(pick("harvest", "harvest_period"), shiftDays)) return "fruiting";
    return "vegetative";
  }

  // Olives (perennial)
  if (gen === "olive") {
    if (isNowInPeriod(pick("dormant", "dormant_period"), shiftDays)) return "vegetative"; // dormant treated as low-demand vegetative
    if (isNowInPeriod(pick("flowering", "flowering_period"), shiftDays)) return "flowering";
    if (isNowInPeriod(pick("fruit_set", "fruit_set_period"), shiftDays)) return "fruit_dev";
    if (isNowInPeriod(pick("ripening", "ripening_period"), shiftDays)) return "ripening";
    return "vegetative";
  }

  // Default fallback
  // B5 FIX: Νέα crop groups πριν default
  if (gen === "cerealCrops") {
    if (isNowInPeriod(pick("germination", "germination_period"), shiftDays)) return "germination";
    if (isNowInPeriod(pick("tillering", "tillering_period"), shiftDays)) return "tillering";
    if (isNowInPeriod(pick("stem_elongation", "stem_elongation_period"), shiftDays)) return "stem_elongation";
    if (isNowInPeriod(pick("anthesis", "anthesis_period"), shiftDays)) return "anthesis";
    if (isNowInPeriod(pick("grain_filling", "grain_filling_period"), shiftDays)) return "grain_filling";
    return "vegetative";
  }

  if (gen === "stoneFruits") {
    if (isNowInPeriod(pick("dormancy", "dormancy_period"), shiftDays)) return "dormancy";
    if (isNowInPeriod(pick("bloom", "bloom_period"), shiftDays)) return "bloom";
    if (isNowInPeriod(pick("fruit_dev", "fruit_dev_period"), shiftDays)) return "fruit_dev";
    if (isNowInPeriod(pick("harvest", "harvest_period"), shiftDays)) return "harvest";
    return "vegetative";
  }

  if (gen === "citrusFruits") {
    if (isNowInPeriod(pick("flowering", "flowering_period"), shiftDays)) return "flowering";
    if (isNowInPeriod(pick("fruit_set", "fruit_set_period"), shiftDays)) return "fruit_set";
    if (isNowInPeriod(pick("fruit_dev", "fruit_dev_period"), shiftDays)) return "fruit_dev";
    return "vegetative";
  }

  if (gen === "nutCrops") {
    if (isNowInPeriod(pick("dormancy", "dormancy_period"), shiftDays)) return "dormancy";
    if (isNowInPeriod(pick("bloom", "bloom_period"), shiftDays)) return "bloom";
    if (isNowInPeriod(pick("fruit_dev", "fruit_dev_period"), shiftDays)) return "fruit_dev";
    if (isNowInPeriod(pick("harvest", "harvest_period"), shiftDays)) return "harvest";
    return "vegetative";
  }

  if (["industrialCrops","subTropicalFruits","pomeFruits","specialtyMediterranean","ornamentalCrops"].includes(gen)) {
    if (isNowInPeriod(pick("flowering", "flowering_period"), shiftDays)) return "flowering";
    if (isNowInPeriod(pick("harvest", "harvest_period"), shiftDays)) return "harvest";
    if (isNowInPeriod(pick("fruit_dev", "fruit_dev_period"), shiftDays)) return "fruit_dev";
    return "vegetative";
  }

  // Original default fallback
  return legacyRoot?.stage || crop?.stage || "vegetative";
}

// ── E3: GDD-based Crop Phenology ────────────────────────────────────────
// Ref: Paredes et al. 2025 (FAO56rev Tables 5-6), McMaster & Wilhelm 1997
// Uses accumulated thermal time to determine crop growth stage.
// More accurate than calendar (±5 days vs ±15 days).

// ── T-GDD-SEASON-01 (μεταφορά SAGFIX_105 από runPerTich_test.js) ─────────
// Το `gdd_crop_accumulated` μεγάλωνε μονότονα για όλη τη ζωή του αγρού και τίποτα
// δεν το μηδένιζε ποτέ. Με κατώφλια κορωνέικης {0, 50, 480, 1865} και κρητική
// χρονιά, το 1865 περνιέται μέσα στο πρώτο έτος — και μετά η ελιά ανέφερε
// «ripening» ΓΙΑ ΠΑΝΤΑ, ακόμη και τον Ιανουάριο, οδηγώντας λάθος βάθος ρίζας και
// λάθος απαίτηση θρέψης για την υπόλοιπη ζωή του ελαιώνα.
//
// Το biofix είναι η ημέρα που ανοίγει η εποχή, με σειρά προτεραιότητας:
//   1. η αρχή της πρώτης δηλωμένης περιόδου του αγρότη για την κατηγορία, αλλιώς
//   2. προεπιλογή κατηγορίας: 1 Οκτωβρίου για τα σιτηρά (φθινοπωρινή σπορά που
//      περνά στον επόμενο χρόνο), 1 Ιανουαρίου για όλα τα άλλα.
// Το κλειδί εποχής είναι το ΕΤΟΣ ΤΗΣ ΠΙΟ ΠΡΟΣΦΑΤΗΣ ΕΜΦΑΝΙΣΗΣ αυτής της ημέρας,
// ώστε παράθυρο που περνά την πρωτοχρονιά να μην κόβεται στη μέση. Όταν αλλάξει
// το κλειδί, ο συσσωρευτής ξεκινά από το μηδέν.
//
// ΑΣΦΑΛΕΙΑ ΑΝΑΠΤΥΞΗΣ: στο ΠΡΩΤΟ tick δεν υπάρχει προηγούμενο κλειδί, οπότε
// _seasonRolled = false -> ΚΑΜΙΑ επαναφορά τώρα. Απλώς καταγράφεται το κλειδί.
// Η πρώτη πραγματική επαναφορά θα γίνει την 1η Ιανουαρίου 2027.
// ============================================================================
// SAG-GDD-ANCHOR-01 — εποχική άγκυρα βαθμοημερών, ανεξάρτητη από την εγκατάσταση
// ----------------------------------------------------------------------------
// ΤΟ ΠΡΟΒΛΗΜΑ (μετρημένο 19/8/2026): ο συσσωρευτής ξεκινούσε όταν μπήκε ο αγρός
// στο σύστημα. Δώδεκα ελαιώνες του ίδιου νομού έδειχναν 8 έως 309 βαθμοημέρες,
// ενώ η πραγματική συσσώρευση από 1/1 στο βόρειο Ρέθυμνο είναι ~1.870. Υστέρηση
// 6,6× έως 254×. Κανένα κατώφλι δεν μπορούσε να βαθμονομηθεί.
//
// Η ΛΥΣΗ, σε τρία σκέλη:
//   1. ΑΓΚΥΡΑ: 1η Ιανουαρίου, κάθε χρόνο. Είναι η σύμβαση της βιβλιογραφίας
//      (Gonçalves et al. 2011, J. Pest Sci. — «accumulation since January 1»)
//      και ήδη συνεπής με τον πυρηνοτρήτη του προφίλ (180/550 -> 16 Απρ / 2 Ιουν).
//   2. SEED: αγρός που μπαίνει μέσα στη σεζόν δεν ξεκινά από το μηδέν — το κενό
//      1/1 έως σήμερα συμπληρώνεται από κλιματικές νόρμες της ζώνης του.
//   3. ΧΩΡΙΣ ΜΟΝΙΜΟ BIAS: το seed είναι απλώς η αρχική τιμή του τρέχοντος έτους.
//      Στον επόμενο μηδενισμό (1/1) ο μετρητής ξεκινά από 0 με ΠΡΑΓΜΑΤΙΚΑ
//      δεδομένα αισθητήρα. Η εκτίμηση σβήνει από μόνη της, δεν συσσωρεύεται.
//
// Το seed σημαίνεται ρητά (gdd_seeded_<εχθρός>) ώστε ο γεωπόνος να ξέρει ότι το
// πρώτο κομμάτι της σεζόν είναι εκτίμηση και όχι μέτρηση.
// ============================================================================
// Μέσες μηνιαίες θερμοκρασίες και ημιπλάτος ημερήσιου κύκλου ανά ζώνη.
// Επιλογή ζώνης από το γεωγραφικό πλάτος του αγρού.
const _SAG_CLIMATE_ZONES = [
  { maxLat: 35.8, name: 'Κρήτη / Νότιο Αιγαίο',
    mean: [9.4, 9.7, 11.7, 14.7, 19.0, 23.1, 25.2, 25.0, 22.4, 18.4, 14.6, 11.0],
    amp:  [2.7, 3.0,  3.6,  4.0,  4.3,  4.5,  4.4,  4.3,  4.1,  3.4,  3.0,  2.5] },
  { maxLat: 38.6, name: 'Νότια & Κεντρική Ελλάδα',
    mean: [10.2, 10.7, 13.0, 16.7, 21.7, 26.4, 29.0, 28.7, 24.5, 19.6, 15.1, 11.7],
    amp:  [ 3.9,  4.2,  4.7,  5.2,  5.6,  5.8,  5.7,  5.6,  5.2,  4.6,  4.0,  3.7] },
  { maxLat: 99,   name: 'Βόρεια Ελλάδα',
    mean: [5.2, 6.9, 10.0, 14.6, 19.9, 24.4, 26.7, 26.3, 22.0, 16.6, 11.2, 6.8],
    amp:  [3.5, 4.2,  4.9,  5.4,  5.8,  6.0,  6.1,  6.0,  5.4,  4.6,  3.8, 3.3] },
];
const _SAG_DIM = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];

function _sagClimateZone(latitude) {
  const lat = Number(latitude);
  if (!Number.isFinite(lat)) return _SAG_CLIMATE_ZONES[0];
  for (const z of _SAG_CLIMATE_ZONES) if (lat < z.maxLat) return z;
  return _SAG_CLIMATE_ZONES[_SAG_CLIMATE_ZONES.length - 1];
}

// Βαθμοημέρες από 1 Ιανουαρίου έως nowDate, με την ΙΔΙΑ ωριαία λογική που
// χρησιμοποιεί ο πυρήνας για τα πραγματικά δεδομένα (clamp στην οροφή,
// μηδέν κάτω από το Tbase) — ώστε το seed να είναι στην ίδια κλίμακα.
function _sagClimateGddSinceJan1(Tbase, Tupper, nowDate, latitude, elevM) {
  const tb = Number(Tbase), tu = Number.isFinite(Number(Tupper)) ? Number(Tupper) : 50;
  if (!Number.isFinite(tb)) return 0;
  const now = (nowDate instanceof Date && !isNaN(nowDate.getTime())) ? nowDate : new Date();
  const zone = _sagClimateZone(latitude);
  // T-THERMAL-01: οι νόρμες είναι ΠΕΔΙΝΕΣ — κατεβαίνουμε στο υψόμετρο του αγρού.
  const _dz = _sagLapseDelta(elevM);
  const mo = now.getMonth(), day = now.getDate();
  const dayGdd = (m) => {
    let s = 0;
    for (let h = 0; h < 24; h++) {
      const T = (zone.mean[m] - _dz) + zone.amp[m] * Math.sin(2 * Math.PI * (h - 9) / 24);
      const Te = Math.min(T, tu);
      if (Te > tb) s += (Te - tb) / 24;
    }
    return s;
  };
  let total = 0;
  for (let m = 0; m < mo; m++) total += _SAG_DIM[m] * dayGdd(m);
  total += Math.max(0, day - 1) * dayGdd(mo);
  return Math.max(0, parseFloat(total.toFixed(2)));
}

// ══════════════════════════════════════════════════════════════════════════
// T-GDD-FROMPLANTING-01 (v50.99) · ΤΟ ΦΥΤΟ ΔΕΝ ΞΕΡΕΙ ΠΟΤΕ ΕΙΝΑΙ ΠΡΩΤΟΧΡΟΝΙΑ
//
// Ο συσσωρευτής της ΚΑΛΛΙΕΡΓΕΙΑΣ σπερνόταν με τις βαθμοημέρες «από 1 Ιανουαρίου»
// ενώ η σεζόν του ανοίγει στην ημερομηνία ΦΥΤΕΥΣΗΣ. Δύο διαφορετικές άγκυρες
// στον ίδιο αριθμό. Μετρημένο σφάλμα στη ζώνη Κρήτης, στο σπέρμα ενός νέου αγρού:
//     ντομάτα μεταφ. 1/4    +107  (+6 %)      σκόρδο φύτ. 15/10   −1.092 (−36 %)
//     ντομάτα μεταφ. 15/5   +374  (+25 %)     κουκιά σπορά 20/10    −708 (−50 %)
//     πιπεριά μεταφ. 1/5    +248  (+15 %)     σιτάρι σπορά 1/10   −1.349 (−45 %)
// Οι ανοιξιάτικες υπερεκτιμούνταν, οι φθινοπωρινές υποτιμούνταν στο μισό.
//
// ΠΡΟΣΟΧΗ: ΔΕΝ αλλάζει ο συσσωρευτής των ΕΝΤΟΜΩΝ. Τα μοντέλα βαθμοημερών εντόμων
// είναι όντως ημερολογιακά (biofix 1 Ιανουαρίου) — εκεί το 1/1 είναι ΣΩΣΤΟ.
function _sagClimateGddSpan(Tbase, Tupper, fromDate, toDate, latitude, elevM) {
  const tb = Number(Tbase), tu = Number.isFinite(Number(Tupper)) ? Number(Tupper) : 50;
  if (!Number.isFinite(tb)) return 0;
  if (!(fromDate instanceof Date) || isNaN(fromDate.getTime())) return 0;
  if (!(toDate instanceof Date) || isNaN(toDate.getTime())) return 0;
  if (toDate <= fromDate) return 0;
  const zone = _sagClimateZone(latitude);
  // T-THERMAL-01: ίδια διόρθωση υψομέτρου με τη _sagClimateGddSinceJan1.
  const _dz = _sagLapseDelta(elevM);
  const cache = new Array(12).fill(null);
  const dayGdd = (m) => {
    if (cache[m] !== null) return cache[m];
    let s = 0;
    for (let h = 0; h < 24; h++) {
      const T = (zone.mean[m] - _dz) + zone.amp[m] * Math.sin(2 * Math.PI * (h - 9) / 24);
      const Te = Math.min(T, tu);
      if (Te > tb) s += (Te - tb) / 24;
    }
    cache[m] = s;
    return s;
  };
  // Φραγμός: ποτέ πάνω από 400 ημέρες. Μια ετήσια καλλιέργεια δεν ζει τόσο, και
  // χωρίς αυτόν μια χαλασμένη ημερομηνία 1970 θα γύριζε δεκάδες χιλιάδες κύκλους.
  const MAX_D = 400;
  // T-DST-DAYSTEP-01: ΗΜΕΡΟΛΟΓΙΑΚΗ αύξηση, ΟΧΙ +86.400.000 ms. Η αλλαγή ώρας
  // του Μαρτίου έκανε το διάστημα 1/3 - 30/4 να μετρά 60 ημέρες αντί για 61 —
  // ακριβώς μέσα στην περίοδο μεταφύτευσης των ανοιξιάτικων.
  let total = 0, d = new Date(fromDate.getTime()), n = 0;
  while (d < toDate && n < MAX_D) {
    total += dayGdd(d.getMonth());
    d = new Date(d.getTime());
    d.setDate(d.getDate() + 1);
    n++;
  }
  return Math.max(0, parseFloat(total.toFixed(2)));
}

// T-TICKGAP-01 (v50.101) · ΤΟ ΚΕΝΟ ΤΟΥ ΠΑΛΜΟΥ ΓΕΜΙΖΕΙ, ΔΕΝ ΧΑΝΕΤΑΙ
//
// Ο παλμός κλειδώνει στις 2 ώρες (_SAG_TICK_H_MAX) ώστε μια διακοπή να μη
// ρίξει ψεύτικο άλμα. Σωστό — αλλά ό,τι περίσσευε ΧΑΝΟΤΑΝ. Στο log παραγωγής:
// «ο παλμός κάλυψε 2,00 ώρες (πραγματικό διάστημα 175΄)» -> 55 λεπτά στο κενό.
// Το σφάλμα έχει ΠΑΝΤΑ την ίδια φορά: προς τα κάτω. Τα ορόσημα των εντόμων και
// τα στάδια της καλλιέργειας έρχονται λίγο αργά, ποτέ νωρίς.
//
// ΤΩΡΑ: οι αζήτητες ώρες συμπληρώνονται με τον ΚΛΙΜΑΤΟΛΟΓΙΚΟ ρυθμό της ημέρας
// και της ζώνης — την ίδια μηχανή που σπέρνει τους νέους αγρούς. Είναι ΕΚΤΙΜΗΣΗ
// και δηλώνεται. Πάνω από 48 ώρες ΔΕΝ συμπληρώνεται: εκεί ο αγρός έχει
// μεγαλύτερο πρόβλημα και πρέπει να το δει άνθρωπος, όχι να το κρύψει μια
// κλιματολογική παρεμβολή.
let _SAG_TICK_GAP_H = 0;
let _SAG_TICK_GAP_LOGGED = false;
const _SAG_TICK_GAP_MAX_H = 48;
function _sagTickGapHours() {
  const g = Number(_SAG_TICK_GAP_H);
  if (!Number.isFinite(g) || g <= 0) return 0;
  return Math.min(g, _SAG_TICK_GAP_MAX_H);
}
// Κλιματολογικές βαθμοημέρες για N ώρες γύρω από μια ημερομηνία.
function _sagClimateGddForHours(Tbase, Tupper, atDate, hours, latitude, elevM) {
  const h = Number(hours);
  if (!Number.isFinite(h) || h <= 0) return 0;
  const d = (atDate instanceof Date && !isNaN(atDate.getTime())) ? atDate : new Date();
  const a = new Date(d.getTime()); a.setDate(a.getDate() - 1);
  const oneDay = _sagClimateGddSpan(Tbase, Tupper, a, d, latitude, elevM);
  if (!Number.isFinite(oneDay) || oneDay <= 0) return 0;
  return parseFloat((oneDay * h / 24).toFixed(3));
}

// Το κλειδί εποχής είναι «YYYY-MMDD» — και το YYYY είναι το έτος που ΑΝΟΙΞΕ η
// σεζόν, όχι το τρέχον. Έτσι μια σεζόν Οκτωβρίου διαβάζεται σωστά τον Μάρτιο.
function _sagSeasonStartDate(seasonKey) {
  const m = String(seasonKey || '').match(/^(\d{4})-(\d{2})(\d{2})$/);
  if (!m) return null;
  const y = Number(m[1]), mo = Number(m[2]), day = Number(m[3]);
  if (!(mo >= 1 && mo <= 12 && day >= 1 && day <= 31)) return null;
  const d = new Date(y, mo - 1, day);
  if (isNaN(d.getTime())) return null;
  // T-SEASONKEY-ROUNDTRIP-01: ανύπαρκτη ημερομηνία (π.χ. 31 Φεβρουαρίου) η Date
  // την κυλάει σιωπηλά στον επόμενο μήνα. Δεν τη δεχόμαστε.
  if (d.getFullYear() !== y || d.getMonth() !== mo - 1 || d.getDate() !== day) return null;
  return d;
}

