// T-CROPSEASON-01 (v50.98) — ΤΟ ΑΝΟΙΓΜΑ ΣΕΖΟΝ ΕΙΝΑΙ ΙΔΙΟΤΗΤΑ ΤΗΣ ΚΑΛΛΙΕΡΓΕΙΑΣ,
// ΟΧΙ ΤΗΣ ΚΑΤΗΓΟΡΙΑΣ. Η προεπιλογή των vegetableCrops (1 Ιανουαρίου) είναι
// σωστή για ανοιξιάτικη ντομάτα και ΛΑΘΟΣ για κάθε φθινοπωρινή φύτευση:
// μετρήθηκε ότι σκόρδο φυτεμένο 15/10 χωρίς δηλωμένη ημερομηνία μηδένιζε τον
// συσσωρευτή βαθμοημερών την 1η Ιανουαρίου — στη μέση της περιόδου του.
// ΔΗΛΩΝΟΝΤΑΙ ΜΟΝΟ οι καλλιέργειες που στην Ελλάδα είναι ΑΝΑΜΦΙΒΟΛΑ φθινοπωρινές.
// Λάχανο, μπρόκολο, μαρούλι και κρεμμύδι σπέρνονται ΚΑΙ άνοιξη ΚΑΙ φθινόπωρο:
// μια σταθερή προεπιλογή θα χαλούσε τη μία από τις δύο, οπότε γι' αυτά
// στηριζόμαστε στη δηλωμένη ημερομηνία του αγρότη (που έγινε υποχρεωτική στη
// φόρμα) και ειδοποιούμε στο log όσο λείπει.
const _SAG_CROP_SEASON_OPENER = {
  'vegetableCrops/garlic':    { key: 'germination', mo: 10, day: 15 },
  'vegetableCrops/faba_bean': { key: 'germination', mo: 10, day: 20 },
};
// Καλλιέργειες με ΔΙΦΟΡΟΥΜΕΝΗ εποχή: χωρίς δήλωση, η προεπιλογή είναι εικασία.
const _SAG_SEASON_WARNED = new Set();
const _SAG_SEASON_AMBIGUOUS = new Set([
  'vegetableCrops/onion', 'vegetableCrops/cabbage', 'vegetableCrops/broccoli',
  'vegetableCrops/lettuce', 'vegetableCrops/potato', 'vegetableCrops/carrot',
]);

function _sagSeasonKey(parameters, nowDate) {
  const gen = parameters && parameters.cultivation_type_general;
  const _ck = gen + '/' + (parameters && parameters.cultivation_type);
  const def = _SAG_CROP_SEASON_OPENER[_ck] || _SAG_SEASON_OPENER[gen] || { key: null, mo: 1, day: 1 };
  let mo = def.mo, day = def.day;
  // η δήλωση του ίδιου του αγρότη υπερισχύει της προεπιλογής κατηγορίας
  const declared = parameters && parameters.periods && def.key ? parameters.periods[def.key] : null;
  const startStr = declared && typeof declared === 'object' ? declared.start : null;
  if (startStr) {
    const m = String(startStr).trim().match(/^(?:\d{4}-)?(\d{2})-(\d{2})/);
    if (m) {
      const _mo = Number(m[1]), _day = Number(m[2]);
      if (_mo >= 1 && _mo <= 12 && _day >= 1 && _day <= 31) { mo = _mo; day = _day; }
    }
  }
  const _warnKey = String(parameters?.name || '—') + '|' + _ck;
  if (!startStr && _SAG_SEASON_AMBIGUOUS.has(_ck) && !_SAG_SEASON_WARNED.has(_warnKey)) {
    _SAG_SEASON_WARNED.add(_warnKey);
    console.log('[' + (parameters?.name || '—') + '] T-CROPSEASON-01: η καλλιέργεια «'
      + _ck + '» σπέρνεται ΚΑΙ άνοιξη ΚΑΙ φθινόπωρο, αλλά ΔΕΝ έχει δηλωμένη '
      + 'ημερομηνία φύτευσης. Η σεζόν των βαθμοημερών ανοίγει στην προεπιλογή '
      + String(day).padStart(2, '0') + '/' + String(mo).padStart(2, '0')
      + ' — αν η φύτευση έγινε φθινόπωρο, ο συσσωρευτής θα μηδενιστεί στη μέση '
      + 'της καλλιέργειας. Δηλώστε την ημερομηνία στη φόρμα του αγρού.');
  }
  const now = (nowDate instanceof Date && !isNaN(nowDate.getTime())) ? nowDate : new Date();
  const y = now.getFullYear();
  const opened = ((now.getMonth() + 1) * 100 + now.getDate()) >= (mo * 100 + day);
  return String(opened ? y : y - 1) + '-' + String(mo).padStart(2, '0') + String(day).padStart(2, '0');
}
