// Προσαρμογή του p στη ζήτηση της ημέρας (FAO-56 Πίν. 22, σημείωση 3):
// σε υψηλή ETc το φυτό στρεσάρεται νωρίτερα, άρα ποτίζουμε νωρίτερα.
function _sagFao56P(cropKey, ETc_mm_day) {
  const base = (_SAG_FAO56_P[cropKey] || {}).p;
  if (!Number.isFinite(base)) return null;
  if (!Number.isFinite(ETc_mm_day) || ETc_mm_day <= 0) return base;
  return Math.min(0.8, Math.max(0.1, base + 0.04 * (5 - ETc_mm_day)));
}

// Ο πυρήνας του μοντέλου. Καθαρή συνάρτηση: ίδιες είσοδοι -> ίδια έξοδος,
// καμία παρενέργεια, ώστε να ελέγχεται εξαντλητικά.
function _sagFao56Balance(o) {
  if (!o || typeof o !== 'object') return { ok: false };
  const FC = Number(o.fieldCapacityPct), WP = Number(o.wiltingPointPct);
  const theta = Number(o.moisturePct), Zr = Number(o.controlDepthMm);
  if (!Number.isFinite(FC) || !Number.isFinite(WP) || !Number.isFinite(theta)
      || !Number.isFinite(Zr) || Zr <= 0 || !(FC > WP)) return { ok: false };
  const p = Number(o.p);
  if (!Number.isFinite(p) || p <= 0 || p >= 1) return { ok: false };

  const TAW = (FC - WP) * Zr / 100;
  const RAW = p * TAW;
  // Το έλλειμμα φράσσεται στο [0, TAW]: αισθητήρας πάνω από την υδατοϊκανότητα
  // δεν δίνει αρνητικό έλλειμμα, και κάτω από το σημείο μάρανσης δεν δίνει
  // έλλειμμα μεγαλύτερο από όσο νερό χωράει το έδαφος.
  const DrRaw = (FC - theta) * Zr / 100;
  const Dr = Math.min(TAW, Math.max(0, DrRaw));
  const overFC = DrRaw < 0;

  let Ks = 1;
  if (Dr > RAW) {
    const denom = (1 - p) * TAW;
    Ks = denom > 0 ? Math.min(1, Math.max(0, (TAW - Dr) / denom)) : 0;
  }
  return { ok: true, TAW, RAW, Dr, p, Ks, overFC,
           depletionPct: TAW > 0 ? (Dr / TAW) * 100 : 0,
           dueByRAW: Dr >= RAW && Dr > 0 };
}
// ── End T-FAO56-01 ──────────────────────────────────────────────────────


