    const tol = Number.isFinite(Number(tolOverride))
      ? Number(tolOverride) : Number(_prof?.max_tolerance_ECe);
    const _fmt = (v, d) => Number(v).toLocaleString('el-GR', { maximumFractionDigits: d });
    // Αν η συσκευή στέλνει τα αριθμημένα κανάλια, το γυμνό `conduct_soil` είναι
