function _sagSeriesStats(rows, variable) {
  const vals = [], times = [];
  for (const r of (Array.isArray(rows) ? rows : [])) {
    if (!r || r.variable !== variable) continue;
    const v = Number(r.value);
    if (!Number.isFinite(v)) continue;
    vals.push(v);
    const t = Date.parse(r.time);
    if (Number.isFinite(t)) times.push(t);
  }
  if (!vals.length) return null;
  let mn = vals[0], mx = vals[0];
  const seen = {};
  for (const v of vals) {
    if (v < mn) mn = v;
    if (v > mx) mx = v;
    seen[v.toFixed(4)] = 1;
  }
  const spanH = times.length > 1
    ? (Math.max.apply(null, times) - Math.min.apply(null, times)) / 3600000 : 0;
  return { n: vals.length, distinct: Object.keys(seen).length, min: mn, max: mx,
    range: mx - mn, spanH };
}

// ── Ανίχνευση βλαβών ενός οργάνου ──────────────────────────────────────────
// Κάθε βλάβη φέρει: ΤΙ ΣΥΜΒΑΙΝΕΙ · η αιτιολόγηση · ΤΙ ΝΑ ΚΑΝΕΤΕ.
// (v44: η ετικέτα «ΓΙΑΤΙ ΤΟ ΞΕΡΟΥΜΕ:» αφαιρέθηκε από την ΕΞΟΔΟ — τα τρία
//  πεδία `what`/`why`/`act` παραμένουν, αλλάζει μόνο η παρουσίαση.)
// `kill: true` σημαίνει ότι η μέτρηση είναι ΑΠΟΔΕΔΕΙΓΜΕΝΑ ΑΚΥΡΗ και τα κανάλια
// του οργάνου αποσύρονται από κάθε υπολογισμό.
function _sagDetectFaults(dev, data, ctx) {
  const out = [];
  const nm = dev.n;
  const t = dev.t;

  if (!t) {
    out.push({ dev: nm, kill: true, title: 'Χωρίς δηλωμένο τύπο',
      what: 'Λείπει η ετικέτα type — όλες οι μετρήσεις αγνοούνται.',
      act: 'Δήλωση τύπου στη φόρμα παραμετροποίησης.' });
    return out;
  }
  if (!_SAG_DEV_EXPECT[t]) {
    out.push({ dev: nm, kill: true, title: 'Άγνωστο μοντέλο οργάνου',
      what: 'Τύπος «' + t + '» μη χαρτογραφημένος — οι μετρήσεις χάνονται.',
      act: 'Προσθήκη μοντέλου στον πυρήνα (διαχειριστής).' });
    return out;
  }
  if (t === 'uc511') return out;

  const exp = _SAG_DEV_EXPECT[t];
  const missing = [], present = [], missingCh = [];
  for (const ch of exp) {
    if (_sagDevDelivered(data, nm, ch.a)) present.push(ch.k);
    else { missing.push(ch.k); missingCh.push(ch); }
  }

  // ── T-QERR-NOTFAULT-01 (logs παραγωγής 20/8) ──────────────────────────
  // ΠΑΝΕΤΕΚ: 6 όργανα κηρύχθηκαν «σιωπηλά» ενώ στην πραγματικότητα είχαν
  // σκάσει τα ΕΡΩΤΗΜΑΤΑ («TypeError: Cannot read properties of null»). Όταν
  // δεν ρωτήσαμε επιτυχώς, ΔΕΝ ΞΕΡΟΥΜΕ ΤΙΠΟΤΑ για το όργανο — και το «δεν
  // ξέρω» δεν επιτρέπεται ποτέ να παρουσιαστεί ως «χάλασε».
  if (dev.qerr > 0 && present.length === 0) {
    out.push({ dev: nm, kill: false, title: 'Δεν ήταν δυνατός ο έλεγχος',
      what: dev.qerr + (dev.qerr === 1 ? ' αποτυχία' : ' αποτυχίες')
        + ' ερωτήματος προς την πλατφόρμα — πιθανό θέμα νέφους, όχι οργάνου.',
      act: 'Καμία ενέργεια· επιτόπιος έλεγχος μόνο αν επιμείνει.' });
    return out;
  }

  // ── ΣΙΩΠΗΛΟ: καμία επικοινωνία μέσα στο 24ωρο παράθυρο ─────────────────
  const ageH = Number.isFinite(dev.ageMin) ? dev.ageMin / 60 : null;
  if (present.length === 0 && (ageH === null || ageH > 24)) {
    out.push({ dev: nm, kill: true, title: 'Το όργανο σιωπά',
      what: (ageH === null ? 'Καμία εκπομπή ποτέ.'
        : ('Καμία εκπομπή εδώ και ' + ageH.toFixed(1) + ' ώρες.')),
      act: '1) Σιωπούν κι άλλα όργανα → gateway. 2) Αλλαγή μπαταρίας — χωρίς μέτρηση τάσης '
        + '(οι λιθίου κρατούν τάση νεκρές). 3) Έλεγχος στυπιοθλίπτη για νερό.' });
    return out;
  }

  // ── ΝΕΚΡΑ ΚΑΝΑΛΙΑ: επικοινωνεί, καμία έγκυρη μέτρηση ──────────────────
  if (present.length === 0) {
    out.push({ dev: nm, kill: true, title: 'Επικοινωνεί αλλά δεν μετράει',
      what: 'Εκπέμπει κανονικά, όλα τα κανάλια άκυρα — αισθητήριο, όχι μπαταρία/δίκτυο.',
      act: _SAG_SOIL_TYPES.indexOf(t) >= 0
        ? '1) Έλεγχος αποκωδικοποιητή/firmware (ίδια εικόνα σε αλλαγή). 2) Καλώδιο και '
          + 'στυπιοθλίπτης για νερό. 3) Καθαρισμός αισθητήρα μόνο με νερό — χωρητικός, '
          + 'όχι λειαντικά/διαλυτικά.'
        : 'Έλεγχος καλωδίου/επαφών· αλλιώς αντικατάσταση αισθητηρίου.' });
    return out;
  }

  // T-STALEDEV-01: ekpempei, alla i freskoteri metrisi tou einai poly palia.
  // DEN kanei return: to organo boreI na echei KAI kollimeni endeixi KAI palia -
  // o agrotis prepei na ta dei kai ta dyo.
  const _stLim = Number(_SAG_STALE_LIMIT_MIN[t]) || 0;
  if (_stLim > 0 && Number.isFinite(dev.ageMin) && dev.ageMin > _stLim) {
    out.push({ dev: nm, kill: false,
      title: 'Εκπέμπει πολύ αραιά',
      what: 'Η φρεσκότερη μέτρησή του είναι ' + (dev.ageMin / 60).toFixed(1)
        + ' ωρών (όριο ' + (_stLim / 60).toFixed(1) + ' h) — τα μοντέλα δεν την '
        + 'δέχονται πια ως τρέχουσα.',
      act: '1) Μπαταρία — χωρίς μέτρηση τάσης (οι λιθίου κρατούν τάση '
        + 'νεκρές). 2) Εμβέλεια/gateway. 3) Στυπιοθλίπτης και επαφές για νερό.' });
  }

  // ── ΚΟΛΛΗΜΕΝΗ ΕΝΔΕΙΞΗ ─────────────────────────────────────────────────
  // Κατώφλι σκόπιμα ΑΥΣΤΗΡΟ: ΜΙΑ και μόνη διακριτή τιμή σε ≥24 δείγματα που
  // απλώνονται σε ≥6 ώρες. Κανένα πραγματικό αισθητήριο δεν δίνει ταυτόσημη
  // τιμή επί 6 ώρες — έχει πάντα θόρυβο τελευταίου ψηφίου.
  // ΓΙΑΤΙ 18 ΩΡΕΣ ΚΑΙ 48 ΔΕΙΓΜΑΤΑ: το παράθυρο πρέπει να περιέχει ΟΛΟΚΛΗΡΟ
  // ημερονύκτιο κύκλο. Σε 18 ώρες:
  //   • η θερμοκρασία εδάφους στα 20 cm μεταβάλλεται πάντα 2-3 °C (ημερήσιο
  //     θερμικό κύμα) — ακινησία είναι φυσικά αδύνατη·
  //   • η υγρασία εδάφους σε ελαιώνα Κρήτης πέφτει 1-2 μονάδες την ημέρα από
  //     τη διαπνοή (3-5 mm/ημέρα) — ακόμη και τον χειμώνα υπάρχει στράγγιση.
  // Με ανάλυση parser ενός δεκαδικού, ΜΙΑ μοναδική τιμή επί 18 ώρες δεν
  // παράγεται από καμία φυσιολογική συνθήκη· μόνο από παγωμένο αισθητήριο.
  const st = dev.stats || {};
  const stuck = [];
  for (const key of Object.keys(st)) {
    const s = st[key];
    if (!s || s.distinct !== 1) continue;
    // Τιμή κολλημένη σε ΑΚΡΟ κλίμακας (0 ή 100) είναι υπογραφή αποσυνδεδεμένου
    // ή κορεσμένου καναλιού — αναγνωρίζεται νωρίτερα, στις 6 ώρες.
    const _dryLeaf = (key === 'leaf_moisture' && s.min === 0);
    const _satAir = (/humidity/.test(key) && s.min === 100);
    const atRail = (s.min === 0 || s.min === 100) && !_dryLeaf && !_satAir;
    if (atRail ? (s.n >= 24 && s.spanH >= 6) : (s.n >= 48 && s.spanH >= 18)) {
      stuck.push({ key, v: s.min });
    }
  }
  if (stuck.length) {
    const isTemp = (k) => /temp|temperature/.test(k);
    const frozenT = stuck.filter(x => isTemp(x.key));
    const nSamp = Math.min.apply(null, stuck.map(x => st[x.key].n));
    const hSpan = Math.max.apply(null, stuck.map(x => st[x.key].spanH));
    const listed = stuck.map(x => x.key + ' = ' + x.v).join(', ');
    const _tempKeys = Object.keys(st).filter(k => isTemp(k));
    const _allTempFrozen = _tempKeys.length > 0 && frozenT.length >= _tempKeys.length;
    if (_allTempFrozen) {
      out.push({ dev: nm, kill: true, title: 'Παγωμένο όργανο',
        what: 'Ίδια τιμή σε ' + nSamp + ' δείγματα / ' + hSpan.toFixed(1) + ' ώρες: ' + listed + '.',
        act: _sagResetHowTo(t) });
      return out;
    }
    // Ακίνητη ΜΟΝΟ η υγρασία, με τη θερμοκρασία να κινείται κανονικά: το όργανο
    // ζει. Είτε το αισθητήριο υγρασίας κόλλησε, είτε ο parser στρογγυλοποιεί
    // χοντρικά σε πολύ σταθερές συνθήκες. ΔΕΝ αποσύρουμε — προειδοποιούμε.
    out.push({ dev: nm, kill: false, title: 'Ακίνητη ένδειξη υγρασίας',
      what: 'Υγρασία αμετάβλητη επί ' + hSpan.toFixed(1) + ' ώρες (' + listed
        + ')· η θερμοκρασία κινείται κανονικά.',
      act: 'Επανέλεγχος στην επόμενη άρδευση/βροχή — αν δεν ανέβει, βλάβη αισθητηρίου. '
        + 'Έλεγχος επαφής αισθητήρα-εδάφους. Οι συμβουλές συνεχίζονται.' });
    return out;
  }

  // ── ΣΟΝΔΑ ΕΚΤΟΣ ΕΔΑΦΟΥΣ ───────────────────────────────────────────────
  // ΦΥΣΙΚΗ: το ημερήσιο θερμικό κύμα αποσβένεται εκθετικά με το βάθος,
  // A(z) = A0·exp(−z/d), με βάθος απόσβεσης d ≈ 10–15 cm σε τυπικά εδάφη.
  // Στα 10 cm το εύρος πέφτει στο ~37 % του ατμοσφαιρικού, στα 20 cm στο ~14 %.
  // Ημερήσιο εύρος αέρα 20 °C ⇒ αναμενόμενο εύρος εδάφους 3–7 °C. Εύρος >12 °C
  // σημαίνει ότι η σόνδα ΔΕΝ βρίσκεται μέσα στο χώμα.
  if (_SAG_SOIL_TYPES.indexOf(t) >= 0) {
    let worst = null;
    for (const key of Object.keys(st)) {
      if (!/temp|temperature/.test(key)) continue;
      const s = st[key];
      if (!s || s.n < 12 || s.spanH < 12) continue;
      if (s.range > 18 && (worst === null || s.range > worst.range)) worst = { key, range: s.range, min: s.min, max: s.max };
    }
    // ΕΠΙΒΕΒΑΙΩΣΗ. Το εύρος ΜΟΝΟ του δεν αρκεί: μαύρο πλαστικό εδαφοκάλυψης,
    // γλάστρα, ή πότισμα με νερό γεώτρησης 17 °C σε χώμα 32 °C δίνουν νόμιμα
    // μεγάλο εύρος στα 10 cm. Σόνδα ΣΤΟΝ ΑΕΡΑ όμως δεν μπορεί να πλαστογραφήσει
    // υγρασία και αγωγιμότητα εδάφους: διαβάζει ~0 και στα δύο.
    let _corrob = false;
    if (worst) {
      const _m = _sagRawNum(data, 'soil_moisture') || _sagRawNum(data, 'soil_moisture1');
      const _ec = _sagRawNum(data, 'conduct_soil') || _sagRawNum(data, 'conduct_soil1');
      _corrob = (Number.isFinite(_m) && _m < 5) || (Number.isFinite(_ec) && _ec < 20);
    }
    if (worst) {
      out.push({ dev: nm, kill: false, title: 'Ο αισθητήρας μάλλον δεν είναι μέσα στο χώμα',
        what: 'Ημερήσιο εύρος θερμοκρασίας εδάφους ' + worst.range.toFixed(1) + ' °C ('
          + worst.min.toFixed(1) + '–' + worst.max.toFixed(1) + ')· θαμμένος αισθητήρας: ≤12 °C.'
          + (_corrob ? ' Υγρασία/αγωγιμότητα ~0 — επιβεβαιωμένη έλλειψη επαφής.' : ''),
        act: 'Επανατοποθέτηση στο ίδιο βάθος/θέση, συμπίεση με το χέρι (όχι πόδι), πότισμα του σημείου.'
          + (_corrob ? '' : ' Εξαιρέσεις με φυσιολογικό μεγάλο εύρος: μαύρο πλαστικό, γλάστρα, κρύο νερό γεώτρησης — οπτικός έλεγχος πρώτα.') });
      return out;
    }
  }

  // ── ΑΙΣΘΗΤΗΡΑΣ ΑΕΡΑ/ΚΟΜΗΣ ΣΤΟΝ ΗΛΙΟ ──────────────────────────────────
  // ΜΕΤΡΗΜΕΝΟ στον στόλο 19-20/8/2026: σε 5 αγρούς με σταθμό ΚΑΙ em320, το
  // em320 έδωσε έως +6,4 °C υψηλότερο μέγιστο και έως +7,1 °C μεγαλύτερο
  // ημερήσιο εύρος από τον σταθμό. Στον ΚΟΥΤΣΑΚΗ κατέγραψε 53,4 °C — πάνω από
  // το ρεκόρ Ελλάδας (48,0 °C, Ελευσίνα 1977). Στον ΚΟΥΤΣΑΚΗ: 54,3 °C.
  // ΔΙΟΡΘΩΣΗ 1/9/2026 (T-CANOPY-SHIELD-02): παλιά αποδίδαμε αυτή την υπογραφή σε
  // «μη σκιασμένο όργανο». Ο χειριστής βεβαίωσε ότι ΟΛΟΙ οι αισθητήρες αέρα του
  // στόλου φέρουν ασπίδα ακτινοβολίας με γρύλιες. Η μεροληψία είναι πραγματική
  // και μετρημένη — η αιτία όμως είναι άλλη: ασπίδα χωρίς εξαναγκασμένο αερισμό
  // μέσα στην κόμη, σε νηνεμία, θερμαίνεται· και το όργανο δεν στέκει στα 2 m.
  if (_SAG_AIR_TYPES.indexOf(t) >= 0) {
    let tmax = null, trange = null;
    for (const key of Object.keys(st)) {
      if (!/temperature$|^temperature$|^air_temperature$/.test(key)) continue;
      const s = st[key];
      if (!s || s.n < 12 || s.spanH < 12) continue;
      tmax = s.max; trange = s.range;
    }
    // Κατώφλια ΑΝΩ του φυσικά δυνατού, ώστε το εύρημα να είναι απόδειξη και όχι
    // εικασία: το ρεκόρ Ελλάδας είναι 48,0 °C (Ελευσίνα 1977) — σκιασμένο όργανο
    // δεν το ξεπερνά. Και η λεκάνη της Μεσαράς δίνει νόμιμα ημερήσιο εύρος έως
    // 26 °C (λίμνασμα ψυχρού αέρα σε ασέληνες νύχτες), οπότε το 22 ήταν πολύ σφιχτό.
    const sunHot = tmax !== null && tmax >= 50;
    const sunSwing = trange !== null && trange > 28;
    if (sunHot || sunSwing) {
      // T-SUN-NOKILL-01 (logs 20/8): στον ΚΟΥΤΣΑΚΗ η απόσυρση αφαίρεσε ΚΑΙ τον
      // κίνδυνο ασθενειών ΚΑΙ τις βαθμοημέρες, αφήνοντας τον αγρό ολόκληρο στο
      // σκοτάδι. ΔΥΣΑΝΑΛΟΓΟ: ο αισθητήρας στον ήλιο δεν δίνει ΑΚΥΡΗ μέτρηση,
      // δίνει ΜΕΡΟΛΗΠΤΙΚΗ (μετρημένο +6,4 °C στο μέγιστο ⇒ ET0 +15,8 %). Αυτό
      // ανήκει στην κλάση «παλαιότητα» (χρησιμοποιήσιμο, ατελές), όχι «βλάβη».
      // Η διόρθωση είναι δουλειά πέντε λεπτών· δεν δικαιολογεί μαύρο ταμπλό.
      out.push({ dev: nm, kill: false, title: 'Ο αισθητήρας αέρα υπερθερμαίνεται',
        what: (sunHot ? ('Μέγιστο ' + tmax.toFixed(1).replace('.', ',') + ' °C') : '')
          + (sunHot && sunSwing ? ', ' : '')
          + (sunSwing ? ('ημερήσιο εύρος ' + trange.toFixed(1).replace('.', ',') + ' °C') : '')
          + ' — πάνω από όσο δικαιολογεί σκιασμένο όργανο στα 2 m.'
          + (ctx.hasStation ? ' Υπάρχει σταθμός — οι συμβουλές δεν επηρεάζονται.' : ''),
        act: 'Με ασπίδα ακτινοβολίας υπερθερμαίνεται μόνο αν δέχεται απευθείας ήλιο, '
          + 'δεν αερίζεται ή πατάει σε σκούρα/μεταλλική επιφάνεια. Ελέγξτε βόρεια '
          + 'πλευρά και καθαρές γρύλιες.' });
    }
  }

  // ── ΣΟΝΔΑ ΕΚΤΟΣ ΖΩΝΗΣ ΥΓΡΑΝΣΗΣ ───────────────────────────────────────
  // ΠΡΟΕΙΔΟΠΟΙΗΣΗ, ΠΟΤΕ ακύρωση: κατά FAO-56 §8.3 το βάθος διαβροχής είναι
  // βροχή / (θFC − θWP). 25 mm σε πηλώδες (TAW ≈ 0,15 m³/m³) διαβρέχουν ~17 cm,
  // οπότε μια ΒΑΘΙΑ σόνδα μπορεί ΝΟΜΙΜΑ να μην το δει. Ελέγχεται μόνο η ΡΗΧΗ.
  if (_SAG_SOIL_TYPES.indexOf(t) >= 0 && ctx.rain24 >= 25 && t !== 'lse01_deep') {
    let flat = null;
    for (const key of Object.keys(st)) {
      if (!/moisture|humidity|water_soil/.test(key)) continue;
      if (/2$/.test(key)) continue;
      const s = st[key];
      if (!s || s.n < 12) continue;
      if (s.range < 0.5) flat = { key, range: s.range };
    }
    if (flat) {
      out.push({ dev: nm, kill: false, title: 'Ο αισθητήρας ίσως είναι εκτός ζώνης ύγρανσης',
        what: 'Βροχή ' + ctx.rain24.toFixed(0) + ' mm στο 24ωρο, ρηχή υγρασία αμετάβλητη (Δ '
          + flat.range.toFixed(2) + ').',
        act: 'Έλεγχος θέσης: εντός ζώνης ύγρανσης σταλάκτη και προβολής κόμης.' });
    }
  }

  // ── ΜΕΡΙΚΗ ΒΛΑΒΗ ─────────────────────────────────────────────────────
  // ΔΥΟ ΕΝΤΕΛΩΣ ΔΙΑΦΟΡΕΤΙΚΕΣ ΑΙΤΙΕΣ ΔΙΝΟΥΝ ΤΗΝ ΙΔΙΑ ΕΙΚΟΝΑ «λείπει κανάλι»:
  //  (α) το κανάλι ΔΕΝ ΗΡΘΕ ΠΟΤΕ  → σπασμένη επαφή/καλώδιο/αισθητήριο.
  //  (β) το κανάλι ΗΡΘΕ αλλά η τιμή ήταν ΦΥΣΙΚΑ ΑΔΥΝΑΤΗ και την έκοψε η πύλη
  //      ευλογοφάνειας → το αισθητήριο ΛΕΙΤΟΥΡΓΕΙ· φταίει ο αποκωδικοποιητής,
  //      η βαθμονόμηση ή η θέση της σόνδας.
  // Η (β) με την οδηγία της (α) στέλνει τον αγρότη να ΑΝΤΙΚΑΤΑΣΤΗΣΕΙ υγιές
  // όργανο. ΠΑΡΑΓΩΓΗ 21/8: ΚΑΜΠΑΝΗΣ, δύο σόνδες, 71,57 % και 71,34 %.
  // Η λίστα απορρίψεων έχει τη μορφή «<όργανο>: <κλειδί>=<τιμή> [εκτός α..β]».
  // Ταιριάζουμε ΜΟΝΟ αυτή τη μορφή: σημαίνει αδιαμφισβήτητα «η τιμή ΗΡΘΕ και
  // ήταν αδύνατη». Τα «όλα τα κανάλια 0 — αποσυνδεδεμένος» ΔΕΝ πιάνονται εδώ,
  // και σωστά: εκείνο είναι πραγματική αποσύνδεση και το χειρίζεται άλλος κλάδος.
  const _rejList = String((data && data._sagRejectedList) || '');
  const _wasRejected = (ch) => ch.a.some(key => _rejList.indexOf(nm + ': ' + key + '=') >= 0);
  const _rejectedHere = missingCh.filter(_wasRejected).map(ch => ch.k);
  const _absent = missingCh.filter(ch => !_wasRejected(ch)).map(ch => ch.k);

  if (_rejectedHere.length) {
    out.push({ dev: nm, kill: false, title: 'Αδύνατη τιμή από το όργανο',
      what: 'Τιμή εκτός φυσικών ορίων σε: ' + _rejectedHere.join(', ')
        + ' (απορρίφθηκε). Αποκωδικοποιητής/βαθμονόμηση/τοποθέτηση — όχι σπασμένη επαφή.',
      act: 'ΟΧΙ αντικατάσταση. 1) Ίδιο σε άλλο όργανο → κοινή αιτία (αποκωδικοποιητής). '
        + '2) Έλεγχος: δεν λιμνάζει, το χώμα εφάπτεται παντού. 3) Αλλιώς επαναβαθμονόμηση.' });
  }
  if (_absent.length) {
    out.push({ dev: nm, kill: false, title: 'Λείπει μέτρηση από το όργανο',
      what: 'Δεν δίνει: ' + _absent.join(', ') + '· τα υπόλοιπα κανάλια κανονικά.',
      act: 'Έλεγχος επαφής/καλωδίου του αισθητηρίου· αλλιώς αντικατάσταση.' });
  }
  return out;
}

// ── Ευκαιρίες αναβάθμισης — διατυπωμένες ως ΟΦΕΛΟΣ ────────────────────────
// ΟΧΙ «σου λείπει», ΟΧΙ ποσοστό κάλυψης. Τι ΑΚΡΙΒΩΣ θα βελτιωνόταν στη λήψη
// απόφασης, με τον μηχανισμό εξηγημένο.
function _sagUpgradeOffers(data, ctx) {
  const out = [];
  // ΚΡΙΝΟΥΜΕ ΑΠΟ ΤΟΝ ΕΞΟΠΛΙΣΜΟ, ΟΧΙ ΑΠΟ ΤΑ ΔΕΔΟΜΕΝΑ. Χαλασμένο όργανο εξακολουθεί
  // να είναι όργανο: ο αγρότης θέλει να το ΕΠΙΣΚΕΥΑΣΕΙ, όχι να αγοράσει δεύτερο.
  const owns = ctx.owns || {};
  const soil = !!owns.soil;
  const soil2 = !!owns.soil2;
  const airT = !!owns.air;
  const rain = !!owns.station;
  const light = !!owns.station;
  const leafW = !!owns.leaf;

  if (!soil && airT) {
    out.push('ΑΙΣΘΗΤΗΡΑΣ ΥΓΡΑΣΙΑΣ ΕΔΑΦΟΥΣ — ακριβής δόση και χρόνος άρδευσης σε λίτρα, '
      + 'αντί για εκτίμηση από τον καιρό. Και ορατή υπεράρδευση, που ευνοεί φυτόφθορα και '
      + 'μυκητολογικές προσβολές.');
  }
  if (soil && !soil2) {
    out.push('ΔΕΥΤΕΡΟ ΒΑΘΟΣ — σταματάτε το πότισμα όταν το νερό έχει ήδη φτάσει βαθιά, και '
      + 'δεν ποτίζετε λίγο όταν έχει βραχεί μόνο η επιφάνεια.');
  }
  // T-COVERED-01 (v50.13): σε καλυμμένη καλλιέργεια το βροχόμετρο είναι
  // άχρηστο — η βροχή δεν φτάνει στο φυτό και ούτως ή άλλως αγνοείται.
  if (!rain && !_SAG_COVERED_ACTIVE) {
    out.push('ΒΡΟΧΟΜΕΤΡΟ — χωρίς βροχή το σύστημα προτείνει άρδευση μετά από νεροποντή. '
      + 'Θα παρακολουθούσε και το ξέπλυμα του ψεκασμού: τα σκευάσματα επαφής χάνονται από '
      + 'τα 10-15 mm, τα διασυστηματικά όχι αφού απορροφηθούν.');
  }
  if (!leafW && airT) {
    out.push('ΑΙΣΘΗΤΗΡΑΣ ΥΓΡΑΣΙΑΣ ΦΥΛΛΟΥ — οι ώρες διαβροχής καθορίζουν τις μυκητολογικές '
      + 'προσβολές· τώρα εκτιμώνται έμμεσα. Άμεση μέτρηση σημαίνει λιγότερους περιττούς '
      + 'ψεκασμούς.');
  }
  if (!light && airT) {
    out.push('ΜΕΤΡΗΣΗ ΗΛΙΑΚΗΣ ΑΚΤΙΝΟΒΟΛΙΑΣ — απαιτείται από τον τύπο FAO-56 της ζήτησης '
      + 'νερού. Χωρίς αυτήν εκτιμάται από τις θερμοκρασίες με σφάλμα 10-20 %, που περνά '
      + 'αυτούσιο στη δόση.');
  }
  return out;
}

// Απόδοση καναλιού σε ΣΥΓΚΕΚΡΙΜΕΝΟ όργανο. Όπου το T-MULTISENSOR-MERGE-01 έχει
// καταγράψει πηγή, η απόδοση είναι ακριβής· αλλού μοιράζεται η πίστωση.
function _sagDevDelivered(data, devName, aliases) {
  const src = (data && data._sagSrc) || {};
  for (const key of aliases) {
    if (!Number.isFinite(_sagRawNum(data, key))) continue;
    const s = src[key];
    if (Array.isArray(s) && s.length) {
      if (s.indexOf(devName) >= 0) return true;
      continue;
    }
    return true;
  }
  return false;
}

// Οι ΣΥΜΒΟΥΛΕΣ που εξαρτώνται από κάθε οικογένεια μετρήσεων. Χρησιμοποιούνται
// για να πούμε στον αγρότη ΤΙ ΑΚΡΙΒΩΣ αποσύρθηκε και γιατί — ποτέ σιωπηλά.
const _SAG_ADVICE_DEPS = [
  { n: 'η δόση και ο χρόνος άρδευσης', keys: ['soil_moisture', 'soil_moisture_avg',
      'soil_moisture1', 'soil_moisture1_avg', 'soil_moisture2', 'soil_moisture2_avg',
      'water_soil', 'soil_humidity'] },
  { n: 'ο δείκτης υδατικής καταπόνησης του φυτού', keys: ['soil_moisture', 'soil_moisture_avg',
      'soil_moisture1', 'soil_moisture1_avg', 'soil_moisture2', 'soil_moisture2_avg',
      'water_soil', 'soil_humidity'] },
  { n: 'ο κίνδυνος ασθενειών', keys: ['air_temperature', 'air_temperature_avg', 'temperature',
      'canopy_temperature_avg'] },
  { n: 'οι βαθμοημέρες και η πρόβλεψη εμφάνισης εντόμων', keys: ['air_temperature',
      'air_temperature_avg', 'temperature', 'canopy_temperature_avg'] },
  { n: 'η παρακολούθηση ανάπτυξης', keys: ['light_intensity', 'light_intensity_sum', 'dli_mol_m2_day'] },
  { n: 'η προστασία από άρδευση σε κρύο έδαφος', keys: ['temp_soil', 'temp_soil_avg',
      'soil_temperature', 'soil_temperature1', 'soil_temperature1_avg',
      'soil_temperature2', 'soil_temperature2_avg'] },
];

function _sagAdviceAlive(data, keys) {
  for (const k of keys) if (Number.isFinite(_sagRawNum(data, k))) return true;
  return false;
}

// ── Ενορχηστρωτής ─────────────────────────────────────────────────────────
// Σειρά: ανίχνευση → ΑΠΟΣΥΡΣΗ των καναλιών που αποδείχθηκαν άκυρα → καταγραφή
// του τι έχασε ο αγρότης → ευκαιρίες αναβάθμισης πάνω στην ΤΕΛΙΚΗ εικόνα.
function _sagSensorFaults(data, fieldName) {
  const H = { faults: [], hidden: [], offers: [], scored: 0 };
  try {
    if (!data || typeof data !== 'object') return H;
    const inv = Array.isArray(data._sagDevInv) ? data._sagDevInv : [];
    const nowMs = Date.now();
    const _ty = inv.map(d => d.t);
    const ctx = {
      // T-STATION-LIVE-01: «υπάρχει σταθμός» πρέπει να σημαίνει «ο σταθμός ΟΔΗΓΕΙ
      // τη θερμοκρασία αναφοράς», όχι «υπάρχει γραμμή σταθμού στην απογραφή».
      // Νεκρός σταθμός καθιστούσε τον έλεγχο επιεική για έναν ηλιαζόμενο em320
      // που στην πραγματικότητα ήταν η ΜΟΝΗ πηγή — και του έλεγε ρητά «δεν
      // αλλοιώνει τις συμβουλές», ενώ ήταν το μόνο που τις αλλοίωνε.
      hasStation: data._sagMetSource === 'station',
      rain24: Math.max(0, Number(_sagRawNum(data, 'rain_height_daily')) || 0),
      owns: {
        soil: _ty.some(t => _SAG_SOIL_TYPES.indexOf(t) >= 0),
        soil2: _ty.some(t => ['lse02', 'se0x', 'lse01_deep'].indexOf(t) >= 0),
        air: _ty.some(t => _SAG_AIR_TYPES.indexOf(t) >= 0),
        station: _ty.indexOf('s2120') >= 0,
        leaf: _ty.indexOf('lms01_ls') >= 0,
      },
    };

    for (const d of inv) {
      // Ηλικία οργάνου = ηλικία της ΦΡΕΣΚΟΤΕΡΗΣ μέτρησής του. Το `last_input`
      // είναι εφεδρεία: parser που γράφει μπαταρία/RSSI το κρατά φρέσκο ενώ ο
      // ΑΙΣΘΗΤΗΡΑΣ έχει πεθάνει — ακριβώς η βλάβη που ψάχνουμε.
      let best = null;
      for (const ch of (_SAG_DEV_EXPECT[d.t] || [])) {
        for (const key of ch.a) {
          // Μόνο κλειδιά που ΑΠΟΔΕΔΕΙΓΜΕΝΑ πέρασαν από αυτό το όργανο. Αλλιώς
          // μια νεκρή σόνδα δανείζεται τη φρεσκάδα της διπλανής της και
          // διαγιγνώσκεται «ζωντανή αλλά χαλασμένο αισθητήριο» — λάθος επισκευή.
          const _s = (data._sagSrc || {})[key];
          if (Array.isArray(_s) && _s.length && _s.indexOf(d.n) < 0) continue;
          const a = _sagAgeMinutes(data[key], nowMs);
          if (a !== null && (best === null || a < best)) best = a;
        }
      }
      if (best === null) {
        const t = Date.parse(d.li);
        best = Number.isFinite(t) ? Math.max(0, (nowMs - t) / 60000) : null;
      }
      d.ageMin = best;
      if (d.t !== 'uc511') H.scored += 1;
    }

    for (const d of inv) {
      const f = _sagDetectFaults(d, data, ctx);
      for (const x of f) { x.kind = _sagDevKindEl(d.t); H.faults.push(x); }
    }

    // ── ΑΠΟΣΥΡΣΗ ─────────────────────────────────────────────────────────
    // Πρώτα καταγράφουμε ΤΙ ΖΟΥΣΕ, μετά ακυρώνουμε, μετά βλέπουμε τι πέθανε.
    const before = _SAG_ADVICE_DEPS.map(a => _sagAdviceAlive(data, a.keys));
    const killers = {};
    for (const f of H.faults) {
      if (!f.kill) continue;
      const dev = inv.filter(d => d.n === f.dev)[0];
      // `only` = βλάβη ΣΥΓΚΕΚΡΙΜΕΝΟΥ καναλιού· χωρίς αυτό, ΟΛΟ το όργανο.
      let chans;
      if (Array.isArray(f.only) && f.only.length) {
        chans = [];
        for (const k of f.only) { chans.push(k, k + '_avg', k + '_max', k + '_min'); }
      } else {
        chans = (dev && _SAG_DEV_CHANNELS[dev.t]) || [];
      }
      // T-MET-REFERENCE-01 ΑΝΤΙΓΡΑΦΕΙ τη θερμοκρασία κόμης στα κλειδιά αναφοράς
      // `air_temperature_*` όταν δεν υπάρχει σταθμός. Αν δεν τα ακυρώσουμε κι
      // αυτά, η μολυσμένη τιμή επιβιώνει μέσα από το αντίγραφο και η απόσυρση
      // γίνεται φάρσα: ο αγρότης βλέπει συμβουλή από όργανο που κρίναμε άκυρο.
      if (dev && _SAG_AIR_TYPES.indexOf(dev.t) >= 0 && data._sagMetSource !== 'station'
          && !(Array.isArray(f.only) && f.only.length)) {
        chans = chans.concat(['air_temperature_avg', 'air_temperature_max', 'air_temperature_min',
          'air_humidity_avg']);
      }
      // Πόσα ΑΛΛΑ όργανα ίδιου τύπου υπάρχουν; Αν υπάρχουν, κλειδί χωρίς
      // καταγεγραμμένη προέλευση ΔΕΝ αποδίδεται με βεβαιότητα σε αυτό εδώ.
      const _twins = inv.filter(d => d.t === (dev && dev.t) && d.n !== f.dev).length;
      let hit = 0;
      for (const key of chans) {
        if (data[key] === undefined) continue;
        // T-KILL-ATTRIB-01: ακυρώνουμε ΜΟΝΟ ό,τι ανήκει ΑΠΟΔΕΔΕΙΓΜΕΝΑ σε αυτό
        // το όργανο. Το T-MULTISENSOR-MERGE-01 καταγράφει τους συνεισφέροντες·
        // αν συνεισέφερε και άλλος, η τιμή ΔΕΝ είναι του χαλασμένου να τη σβήσει.
        const _src = (data._sagSrc || {})[key];
        if (Array.isArray(_src) && _src.length) {
          if (_src.some(x => x !== f.dev)) continue;
        } else if (_twins > 0) {
          continue;   // χωρίς προέλευση ΚΑΙ με δίδυμο όργανο: δεν ρισκάρουμε
        }
        // Ακυρώνουμε ΟΠΩΣ η πύλη ευλογοφάνειας: κενός πίνακας, ώστε όλοι οι
        // υπάρχοντες φρουροί («Μη διαθέσιμο», T-FIR-NOSOIL-01) να ενεργοποιηθούν
        // αυτόματα, χωρίς νέο μονοπάτι κώδικα.
        data[key] = [];
        hit += 1;
      }
      if (hit) killers[f.dev] = f;
    }
    const after = _SAG_ADVICE_DEPS.map(a => _sagAdviceAlive(data, a.keys));
    const lost = [];
    for (let i = 0; i < _SAG_ADVICE_DEPS.length; i++) {
      if (before[i] && !after[i] && lost.indexOf(_SAG_ADVICE_DEPS[i].n) < 0) {
        lost.push(_SAG_ADVICE_DEPS[i].n);
      }
    }
    if (lost.length) {
      const names = Object.keys(killers);
      H.lostCount = lost.length;
      // T-IRRFAULT-WIRE-01 (v50.77): κρατάμε ΞΕΧΩΡΙΣΤΑ αν έπεσε η ΑΡΔΕΥΣΗ.
      if (lost.indexOf(_SAG_ADVICE_DEPS[0].n) >= 0) {
        H.lostIrr = names.map(n => n + ' — ' + killers[n].title.toLowerCase()).join(' · ');
      }
      H.hidden.push('Αποσύρθηκε: ' + lost.join(', ') + '. Αιτία: '
        + names.map(n => n + ' — ' + killers[n].title.toLowerCase()).join(' · ')
        + '. Οδηγία: κάρτα βλαβών.');
    }

    H.offers = _sagUpgradeOffers(data, ctx);

    if (H.faults.length) {
      console.log('[' + (fieldName || '—') + '] T-SENSORFAULT-01: '
        + H.faults.map(f => f.dev + ' → ' + f.title
            + (f.kill ? (killers[f.dev] ? ' [ΑΠΟΣΥΡΣΗ]' : ' [άκυρο, χωρίς επίπτωση]') : '')).join(' · ')
        + (lost.length ? ' | ΧΑΘΗΚΑΝ: ' + lost.join(', ') : ''));
    }
  } catch (e) {
    try { console.log('[' + (fieldName || '—') + '] T-SENSORFAULT-01 σφάλμα (αγνοήθηκε): ' + (e && e.message)); } catch (_e) {}
  }
  return H;
}

// ── Η κάρτα που βλέπει ο αγρότης ──────────────────────────────────────────
// T-DIVERGENCE-01 (v50.50 · Α6): ορατή προειδοποίηση απόκλισης οργάνων.
// ΚΑΜΙΑ αλλαγή σε υπολογισμούς — μόνο ενημέρωση. Η φάση 2 (επιλογή του πιο
// αξιόπιστου αντί μέσου όρου) απαιτεί απόφαση χρήστη και δεν υλοποιείται εδώ.
// T-DIVERGENCE-EC-01: ΑΛΛΑΞΤΕ ΤΑ ΕΔΩ — δεν υπάρχει δεύτερο σημείο.
const _SAG_EC_DIVERGE_RATIO = 2.5;   // πόσες φορές μεγαλύτερη η μία από την άλλη
const _SAG_EC_DIVERGE_MIN = 200;     // µS/cm — κάτω από αυτό δεν αλλάζει απόφαση

function _sagDivergenceIndicators(data) {
  const out = [];
  try {
    const D = (data && data._sagDiverge) || null;
    const E = (data && data._sagDivergeEc) || null;
    const ks = D ? Object.keys(D) : [];
    const es = E ? Object.keys(E) : [];
    if (!ks.length && !es.length) return out;
    const parts = [];
    if (ks.length) parts.push('υγρασία — '
      + ks.slice(0, 2).map(k => D[k].a + '% ↔ ' + D[k].b + '%').join(' · ')
      + (ks.length > 2 ? ' +' + (ks.length - 2) : ''));
    if (es.length) parts.push('αγωγιμότητα — '
      + es.slice(0, 2).map(k => E[k].a + ' ↔ ' + E[k].b + ' µS/cm').join(' · ')
      + (es.length > 2 ? ' +' + (es.length - 2) : ''));
    const _what = (ks.length && es.length) ? 'υγρασίας και αλατότητας'
      : (es.length ? 'αλατότητας' : 'υγρασίας');
    out.push({ variable: 'sensor_divergence',
      value: 'Τα όργανα ' + _what + ' διαφωνούν',
      metadata: { color: 'orange',
        text: parts.join(' · ') + '. Ο μέσος όρος δεν αντιπροσωπεύει το χωράφι —'
          + ' ελέγξτε τοποθέτηση/βλάβη.'
          + (es.length ? ' Η κάρτα αλατότητας είναι σε αναστολή όσο διαρκεί.' : '')
          + ' Οι υπόλοιποι υπολογισμοί ΔΕΝ έχουν αλλάξει.' } });
  } catch (_e) {}
  return out;
}

function _sagFaultIndicators(data) {
  const out = [];
  try {
    const H = data && data._sagFaults;
    if (!H) return out;
    const faults = H.faults || [];
    const killed = faults.filter(f => f.kill);
    const warn = faults.filter(f => !f.kill);
    const devs = new Set(faults.map(f => f.dev));

    // T-MSG-TECH-01: τηλεγραφικό. Το «γιατί» μένει στα σχόλια του κώδικα.
    const fmt = (f, i) => (i + 1) + ') ' + f.dev + (f.kind ? ' (' + f.kind + ')' : '')
      + ' · ' + f.title + ' — ' + f.what + ' → ' + f.act;

    if (!faults.length) {
      if (H.scored > 0) {
        // Μ10: το πλήθος ανεβαίνει στον τίτλο ώστε να στέκεται μόνος του.
        out.push({ variable: 'sensor_faults',
          value: 'Όργανα: ' + H.scored + ' — όλα λειτουργούν',
          metadata: { color: 'green' } });
      }
    } else {
      const MAXDET = 3;
      const ordered = killed.concat(warn);          // πρώτα ό,τι απέσυρε συμβουλή
      const shown = ordered.slice(0, MAXDET);
      const rest = ordered.slice(MAXDET);
      out.push({ variable: 'sensor_faults',
        value: devs.size + (killed.length
          ? (devs.size === 1 ? ' όργανο χρειάζεται επέμβαση' : ' όργανα χρειάζονται επέμβαση')
          : (devs.size === 1 ? ' όργανο χρειάζεται έλεγχο' : ' όργανα χρειάζονται έλεγχο')),
        metadata: { color: killed.length ? 'red' : 'orange',
          text: shown.map(fmt).join('  ')
            + (rest.length ? ('  +' + rest.length + ' ακόμη: '
                + rest.map(f => f.dev + (f.kind ? ' (' + f.kind + ')' : '') + ' — ' + f.title.toLowerCase()).join(' · ') + '.') : '') } });
    }

    if (!(H.hidden && H.hidden.length)) {
      if (H.scored > 0) {
        out.push({ variable: 'hidden_advice', value: 'Καμία συμβουλή δεν αποσύρθηκε',
          metadata: { color: 'green' } });
      }
    } else {
      out.push({ variable: 'hidden_advice',
        value: (H.lostCount || H.hidden.length)
          + ((H.lostCount || H.hidden.length) === 1 ? ' συμβουλή αποσύρθηκε' : ' συμβουλές αποσύρθηκαν'),
        metadata: { color: 'red',
          text: H.hidden.join(' ')
            + ' Επανέρχονται αυτόματα μόλις αποκατασταθεί το όργανο.' } });
    }

    // ── T-IRRFAULT-WIRE-01 (v50.77 · τελικός έλεγχος) ─────────────────────
    // ΕΥΡΗΜΑ: το widget έχει ΕΤΟΙΜΗ θέση προειδοποίησης στην κορυφή της κάρτας
    // άρδευσης, δεμένη στο `irrigation_sensor_fault` — που ΚΑΝΕΙΣ δεν εξέπεμπε
    // ποτέ. Αποτέλεσμα: στον Κρασαγάκη (3 σόνδες στο 0 %) και στον ΚΕΚ ο αγρότης
    // άνοιγε την άρδευση και δεν έβλεπε ΚΑΜΙΑ εξήγηση γιατί λείπει η δόση.
    // Εκπέμπεται ΜΟΝΟ όταν η άρδευση όντως έπεσε -> μηδέν κόστος στους υγιείς.
    if (H.lostIrr) {
      out.push({ variable: 'irrigation_sensor_fault',
        value: 'Χωρίς έγκυρη υγρασία εδάφους',
        metadata: { color: 'red',
          text: 'Δεν υπολογίζεται δόση άρδευσης: ' + H.lostIrr
            + '. Δείτε την κάρτα βλαβών για το όργανο και την ενέργεια.' } });
    }
    /* ══ T-TEXTDIET-01 (v50.145) · ΤΟ ΕΜΠΟΡΙΚΟ ΚΕΙΜΕΝΟ ΦΕΥΓΕΙ ΑΠΟ ΤΗΝ ΗΜΕΡΗΣΙΑ ΚΑΡΤΑ ══
       ΜΕΤΡΗΜΕΝΟ 19/9 σε 42 αγρούς: 12.669 B, μέσος όρος 302 B — το ΔΕΥΤΕΡΟ ΑΚΡΙΒΟΤΕΡΟ
       κλειδί ΟΛΟΥ του συστήματος, αμέσως μετά το crop_stage. Και δεν λέει στον αγρότη τι
       να κάνει ΣΗΜΕΡΑ στο χωράφι: είναι πρόταση αναβάθμισης εξοπλισμού.
       ΑΠΟΦΑΣΗ ΜΙΧΑΛΗ 19/9: «να πάει σε αναφορά». Εδώ ΜΟΝΟ φυλάσσεται στο `data`·
       γράφεται ΜΙΑ φορά την ημέρα ως ξεχωριστή μεταβλητή `upgrade_report`, ΕΚΤΟΣ bundle —
       μηδέν bytes στο όριο των 10 kB, και η πληροφορία δεν χάνεται. */
    if (H.offers && H.offers.length) {
      data._sagUpgradeReport = 'Το σύστημα λειτουργεί κανονικά με ό,τι έχετε. Τα παρακάτω θα '
        + 'βελτίωναν συγκεκριμένες αποφάσεις: ' + H.offers.join('  ');
      data._sagUpgradeCount = H.offers.length;
    } else if (H.scored > 0) {
      data._sagUpgradeReport = 'Πλήρης εξοπλισμός — καμία εκκρεμότητα αναβάθμισης.';
      data._sagUpgradeCount = 0;
    }
  } catch (_e) { /* η ορατότητα δεν επιτρέπεται να ρίξει τον αγρό */ }
  return out;
}

// ── T-DEVLABEL-01 · ΠΟΙΟ ΦΥΣΙΚΟ ΟΡΓΑΝΟ ΕΙΝΑΙ ΤΟ «ΕΔΑΦΟΣ» ────────────────
// Η κάρτα «Μετρήσεις» έδειχνε μόνο τη φιλική ονομασία του dashboard («Έδαφος
// Ανατολή»). Ούτε ο αγρότης στο τηλέφωνο ούτε ο τεχνικός στο χωράφι μπορούσε να
// δει ΠΟΙΟ κουτί είναι αυτό — ενώ η απογραφή (_sagDevInv) το ήξερε ήδη.
//
// v50.60 (ΑΠΕΤΥΧΕ ΣΤΗΝ ΠΑΡΑΓΩΓΗ): στάλθηκε ως ΞΕΧΩΡΙΣΤΟ σημείο δεδομένων, για να
// μην κοστίσει bytes στο bundle. Το custom widget όμως λαμβάνει ΜΟΝΟ τις
// μεταβλητές που είναι δηλωμένες στην πηγή δεδομένων του dashboard — μια ΝΕΑ
// μεταβλητή δεν φτάνει ποτέ. Μετρήθηκε στο πεδίο 31/8: το widget έδειχνε μόνο το
// είδος οργάνου (από τον εφεδρικό συμπερασμό), ποτέ τον κωδικό.
//
// v50.61: μπαίνει ΜΕΣΑ στο bundle (το μόνο κανάλι που φτάνει σίγουρα), αλλά:
//   • σε ΣΥΜΠΑΓΗ μορφή «id6:όνομα:τύπος|…» — 6 τελευταία ψηφία του id αρκούν για
//     ταύτιση μέσα σε έναν αγρό, το ελληνικό κείμενο του είδους ΔΕΝ ταξιδεύει
//     (ο πίνακας ζει στο widget)· οριακό κόστος ~130-200 B για 6-8 όργανα.
//   • στο `metadata.text`, ΠΡΩΤΟ στη λίστα _LOW_PRIORITY — δηλαδή είναι το ΠΡΩΤΟ
//     που θυσιάζεται όταν στενέψει το bundle. Στους 44 υγιείς αγρούς φαίνεται ο
//     κωδικός· στον έναν κορεσμένο πέφτει σιωπηλά και το widget γυρίζει στο
//     είδος οργάνου. ΚΑΜΙΑ επεξήγηση παθογόνου δεν χάνεται εξαιτίας του.
// T-BATTERY-01: ΜΙΑ γραμμή για όλον τον αγρό. Η ΤΙΜΗ είναι σύντομη και
// επιβιώνει πάντα· το κείμενο είναι ΔΕΔΟΜΕΝΑ (κωδικός:τιμή) που αποκωδικοποιεί
// το widget για να τα δείξει δίπλα σε κάθε όργανο.
function _sagBatteryIndicators(data) {
  try {
    const inv = (data && Array.isArray(data._sagDevInv)) ? data._sagDevInv : [];
    const rows = [], low = [], warn = [];
    let _solarLow = false;
    for (const d of inv) {
      if (!d || !d.b || !Number.isFinite(Number(d.b.v))) continue;
      const _id = String(d.i == null ? '' : d.i).trim();
      if (!_id) continue;
      const _z = _sagBatZone(d.b, d.t, d.bx);
      rows.push(_id.slice(-6) + ':' + d.b.v + d.b.u + (_z ? '\u00B7' + _z : ''));
      if (_sagBatLow(d.b, d.t, d.bx)) {
        low.push(String(d.n || _id));
        if (_sagBatSolar(d.b, d.t, d.bx)) _solarLow = true;
      } else if (_z === 'Χαμηλή') {
        // Ενδιάμεση βαθμίδα: δεν είναι συναγερμός, αλλά ΔΕΝ είναι «εντάξει».
        warn.push(String(d.n || _id));
        if (_sagBatSolar(d.b, d.t, d.bx)) _solarLow = true;
      }
    }
    if (!rows.length) return [];
    return [{
      variable: 'device_battery',
      value: low.length
        ? (low.length === 1 ? '1 όργανο με μπαταρία που τελειώνει'
                            : low.length + ' όργανα με μπαταρία που τελειώνει')
        : (warn.length
          ? (warn.length === 1 ? '1 όργανο με χαμηλή μπαταρία'
                               : warn.length + ' όργανα με χαμηλή μπαταρία')
          : 'Όλες οι μπαταρίες εντάξει'),
      metadata: {
        color: low.length ? 'orange' : (warn.length ? 'yellow' : 'green'),
        text: rows.join('|') + ((low.length || warn.length)
          ? (low.length ? ' — ΤΕΛΕΙΩΝΕΙ: ' + low.join(', ') : '')
            + (warn.length ? ' — ΧΑΜΗΛΗ: ' + warn.join(', ') : '')
            + '. Όριο: κάτω από ' + _SAG_BAT_LOW_PCT + ' % ή '
            + _SAG_BAT_LOW_V.toFixed(1).replace('.', ',') + ' V'
            + _sagBatLimitsNote() + '.'
            + (_solarLow
              ? ' Ένα από τα όργανα φορτίζεται ΗΛΙΑΚΑ: η τάση του πέφτει τη νύχτα '
                + 'και ανεβαίνει με τον ήλιο. Αν η ένδειξη επανέρχεται μέσα στην '
                + 'ημέρα δεν υπάρχει θέμα — αν μένει χαμηλά για μέρες, καθαρίστε '
                + 'το πάνελ ή ελέγξτε για σκίαση.'
              : '')
          : ''),
      },
    }];
  } catch (_e) { return []; }
}

// ── T-FORECAST-01 (v50.108 · 6/9/2026) · Η ΠΡΟΓΝΩΣΗ ΜΠΑΙΝΕΙ ΣΤΟΝ ΠΥΡΗΝΑ ───
// ΕΩΣ ΤΩΡΑ: η πρόγνωση κατέβαινε (analysis «forecast», Open-Meteo, 3 ημέρες
// ωριαία), αποθηκευόταν στη συσκευή του αγρού και τη ΖΩΓΡΑΦΙΖΕ το ταμπλό.
// Ο πυρήνας — αυτός που παίρνει ΟΛΕΣ τις αγρονομικές αποφάσεις — δεν τη
// διάβαζε ΠΟΤΕ: μετρήθηκε 6/9/2026 σε καθαρό εκτελέσιμο κώδικα 489 KB,
// «forecast» 0 εμφανίσεις. Κάθε απόφαση κοίταζε μόνο το παρελθόν.
//
// ΤΙ ΚΑΝΕΙ ΤΩΡΑ: ΜΟΝΟ ΠΡΟΕΙΔΟΠΟΙΗΣΕΙΣ (παγετός, καύσωνας). ΚΑΜΙΑ δόση
// άρδευσης, ΚΑΝΕΝΑΣ κίνδυνος παθογόνου δεν αλλάζει από την πρόγνωση σε αυτή
// την έκδοση. Αυτό είναι ΣΚΟΠΙΜΟ: η πρόγνωση είναι εκτίμηση, και δεν
// επιτρέπεται να μετακινήσει σιωπηλά νούμερα που ο αγρότης ήδη εμπιστεύεται.
//
// ΤΟ ΣΧΗΜΑ (από τον ΙΔΙΟ τον κώδικα της analysis, όχι από εικασία):
//   variable «forecast», value 1, metadata:
//     forecast_base_date «YYYY-MM-DD» (ΤΟΠΙΚΗ ημερομηνία του δείκτη 0)
//     timezone «Europe/Athens» · utc_offset_seconds · forecast_days 3
//     hourly_epoch [δευτερόλεπτα] · hourly {temperature_2m, precipitation,
//     wind_speed_10m (m/s), relative_humidity_2m, ...}
//
// ΓΙΑΤΙ ΔΕΝ ΕΜΠΙΣΤΕΥΟΜΑΣΤΕ ΤΟ hourly_epoch: η analysis μετατρέπει τις ΤΟΠΙΚΕΣ
// ISO ώρες του Open-Meteo («2026-09-06T00:00», ΧΩΡΙΣ ζώνη) με `new Date(iso)`.
// Σε διακομιστή UTC αυτό διαβάζεται ως UTC, άρα οι σφραγίδες βγαίνουν
// μετατοπισμένες κατά τη ζώνη. Ανακατασκευάζουμε τον άξονα χρόνου από τα ΔΥΟ
// πεδία που ΔΕΝ είναι διφορούμενα — «forecast_base_date» και
// «utc_offset_seconds» — και ΣΥΓΚΡΙΝΟΥΜΕ με το hourly_epoch για διάγνωση.
const _SAG_FROST_HARD_C = 0;    // παγετός: σχηματίζεται πάγος
const _SAG_FROST_WARN_C = 2;    // κίνδυνος: το 2 m είναι 2-4 °C πιο ζεστό από
                                // την κόμη σε ασυννέφιαστη, άπνοη νύχτα — γι'
                                // αυτό οι υπηρεσίες καιρού προειδοποιούν στους 2 °C
const _SAG_HEAT_SEVERE_MARGIN_C = 3;   // πάνω από το κρίσιμο της καλλιέργειας
const _SAG_FORECAST_MAX_AGE_H = 12;    // παλαιότερη πρόγνωση = ΔΕΝ προειδοποιούμε
const _SAG_FORECAST_WINDOW_H = 48;     // ορίζοντας προειδοποίησης

function _sagFcHour(ms, tz) {
  try {
    return new Intl.DateTimeFormat('el-GR', { timeZone: tz || 'Europe/Athens',
      weekday: 'short', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(ms));
  } catch (_e) {
    try { return new Date(ms).toISOString().slice(11, 16); } catch (_e2) { return '—'; }
  }
}

// Καθαρή συνάρτηση: ίδιες είσοδοι -> ίδια έξοδος. Καμία παρενέργεια, ώστε να
// ελέγχεται εξαντλητικά χωρίς δίκτυο.
function _sagForecastSeries(meta, nowMs) {
  try {
    if (!meta || typeof meta !== 'object') return { ok: false, why: 'καμία πρόγνωση' };
    const h = meta.hourly;
    if (!h || typeof h !== 'object') return { ok: false, why: 'η πρόγνωση δεν έχει ωριαία δεδομένα' };
    const T = Array.isArray(h.temperature_2m) ? h.temperature_2m : null;
    if (!T || T.length < 6) return { ok: false, why: 'η πρόγνωση δεν έχει θερμοκρασίες' };

    const base = String(meta.forecast_base_date || '');
    if (!/^\d{4}-\d{2}-\d{2}$/.test(base)) return { ok: false, why: 'η πρόγνωση δεν δηλώνει ημερομηνία βάσης' };
    const off = Number(meta.utc_offset_seconds);
    if (!Number.isFinite(off)) return { ok: false, why: 'η πρόγνωση δεν δηλώνει ζώνη ώρας' };

    // ΤΟΠΙΚΟ μεσάνυχτο της ημερομηνίας βάσης, σε πραγματικό UTC
    const t0 = Date.parse(base + 'T00:00:00Z') - off * 1000;
    if (!Number.isFinite(t0)) return { ok: false, why: 'η ημερομηνία βάσης δεν διαβάζεται' };

    // Διάγνωση: συμφωνεί το αποθηκευμένο hourly_epoch;
    let shift = null;
    const ep = meta.hourly_epoch;
    if (Array.isArray(ep) && Number.isFinite(Number(ep[0]))) {
      shift = Math.round((Number(ep[0]) * 1000 - t0) / 1000);
    }

    // Φρεσκάδα: με πρόγνωση χθεσινή ΔΕΝ προειδοποιούμε — ίδια αρχή με το πάγωμα
    // των συσσωρευτών όταν παλιώνει η μέτρηση.
    const runAt = Date.parse(String(meta.run_at || ''));
    const ageH = Number.isFinite(runAt) ? (nowMs - runAt) / 3600000 : null;
    if (ageH !== null && ageH > _SAG_FORECAST_MAX_AGE_H) {
      return { ok: false, ageH: ageH, why: 'η πρόγνωση έχει ' + Math.round(ageH) + ' ώρες' };
    }

    const t = [];
    for (let i = 0; i < T.length; i++) t.push(t0 + i * 3600000);
    if (nowMs > t[t.length - 1]) {
      return { ok: false, ageH: ageH, why: 'η πρόγνωση έχει λήξει' };
    }
    // Δείκτης της πρώτης ΜΕΛΛΟΝΤΙΚΗΣ ώρας
    let i0 = 0;
    while (i0 < t.length && t[i0] < nowMs) i0++;
    const i1 = Math.min(t.length, i0 + _SAG_FORECAST_WINDOW_H);
    if (i1 - i0 < 6) return { ok: false, ageH: ageH, why: 'μένουν λιγότερες από 6 ώρες πρόγνωσης' };

    const num = (a, i) => { const v = Number(Array.isArray(a) ? a[i] : NaN); return Number.isFinite(v) ? v : null; };
    return { ok: true, t: t, T: T, i0: i0, i1: i1, shift: shift, ageH: ageH,
             tz: String(meta.timezone || 'Europe/Athens'),
             rain: h.precipitation, wind: h.wind_speed_10m, rh: h.relative_humidity_2m,
             at: (i) => num(T, i) };
  } catch (_e) { return { ok: false, why: 'η πρόγνωση δεν διαβάστηκε' }; }
}

// ── ΠΑΓΕΤΟΣ · επίπεδο ΑΓΡΟΥ (δεν εξαρτάται από καλλιέργεια) ──────────────
function _sagFrostIndicators(fcs) {
  try {
    if (!fcs || !fcs.ok) return [];
    let mn = Infinity, mnAt = null;
    for (let i = fcs.i0; i < fcs.i1; i++) {
      const v = fcs.at(i);
      if (v === null) continue;
      if (v < mn) { mn = v; mnAt = fcs.t[i]; }
    }
    if (!Number.isFinite(mn) || mnAt === null) return [];
    if (mn > _SAG_FROST_WARN_C) return [];
    const hard = mn <= _SAG_FROST_HARD_C;
    const when = _sagFcHour(mnAt, fcs.tz);
    const v1 = mn.toLocaleString('el-GR', { maximumFractionDigits: 1 });
    // T-WXALERT-01 (v50.131 · μητρώο #88): το όνομα είναι αυτό που ΗΔΗ
    // περιμένει η κάρτα «Καιρικοί Συναγερμοί» του widget — ήταν φτιαγμένη και
    // νεκρή. Το `value` γίνεται βαθμίδα ('emergency'/'warning') γιατί από αυτήν
    // βγάζει το widget το σήμα «Έκτακτο»/«Προειδοποίηση»· η ελληνική λέξη
    // μεταφέρεται στο `label_el` — τη χρειάζεται το push (T-FORECAST-01).
    return [{
      variable: 'weather_alert_frost',
      value: hard ? 'emergency' : 'warning',
      metadata: {
        label_el: hard ? 'Παγετός' : 'Κίνδυνος παγετού',
        color: hard ? 'red' : 'orange',
        text: (hard
          ? 'Η πρόγνωση δίνει ' + v1 + ' °C στις ' + when + '. Σχηματίζεται πάγος: '
            + 'κίνδυνος ζημιάς σε άνθη, νεαρή βλάστηση και καρπούς.'
          : 'Η πρόγνωση δίνει ' + v1 + ' °C στις ' + when + '. Η θερμοκρασία μετριέται '
            + 'στα 2 m· σε ασυννέφιαστη και άπνοη νύχτα η κόμη και το έδαφος είναι '
            + '2-4 °C ΨΥΧΡΟΤΕΡΑ, οπότε μπορεί να πιάσει παγετός.')
          + ' Μέτρα: άρδευση πριν τη νύχτα (το υγρό έδαφος κρατά θερμότητα), '
          + 'ανεμιστήρες ή κάλυψη. Ελέγξτε πρώτα το στάδιο της καλλιέργειας — '
          + 'η ευαισθησία στον παγετό αλλάζει δραματικά με το στάδιο.',
      },
    }];
  } catch (_e) { return []; }
}

// ── ΚΑΥΣΩΝΑΣ · ΑΝΑ ΚΑΛΛΙΕΡΓΕΙΑ (το κρίσιμο όριο είναι της καλλιέργειας) ──
// ΜΙΑ πηγή αλήθειας με το IPSI: το ίδιο `optimal_temp_range.max` που ήδη
// χρησιμοποιεί η calculate_IPSI ως T_heat_crit (γρ. 10521). Καμία νέα σταθερά.
function _sagHeatIndicators(fcs, crop) {
  try {
    if (!fcs || !fcs.ok) return [];
    const crit = Number(crop?.optimal_temp_range?.max) || 36;
    let mx = -Infinity, mxAt = null, hrs = 0;
    for (let i = fcs.i0; i < fcs.i1; i++) {
      const v = fcs.at(i);
      if (v === null) continue;
      if (v >= crit) hrs++;
      if (v > mx) { mx = v; mxAt = fcs.t[i]; }
    }
    if (!Number.isFinite(mx) || mxAt === null || mx < crit) return [];
    const severe = mx >= crit + _SAG_HEAT_SEVERE_MARGIN_C;
    const when = _sagFcHour(mxAt, fcs.tz);
    const v1 = mx.toLocaleString('el-GR', { maximumFractionDigits: 1 });
    const c1 = crit.toLocaleString('el-GR', { maximumFractionDigits: 1 });
    // T-WXALERT-01 (v50.131 · μητρώο #88) — βλ. σχόλιο στον παγετό.
    return [{
      variable: 'weather_alert_heat',
      value: severe ? 'emergency' : 'warning',
      metadata: {
        label_el: severe ? 'Καύσωνας' : 'Ζέστη',
        color: severe ? 'red' : 'orange',
        text: 'Η πρόγνωση δίνει έως ' + v1 + ' °C στις ' + when + ' — πάνω από το '
          + 'κρίσιμο όριο της καλλιέργειας (' + c1 + ' °C), για ' + hrs
          + (hrs === 1 ? ' ώρα' : ' ώρες') + ' μέσα στο επόμενο 48ωρο. '
          + (severe
            ? 'Σε αυτά τα επίπεδα κλείνουν τα στομάτια και η φωτοσύνθεση σταματά· '
              + 'άνθη και νεαροί καρποί μπορεί να πέσουν. '
            : '')
          + 'Ποτίστε ΠΡΙΝ το κύμα, όχι μέσα σε αυτό: το φυτό χρειάζεται γεμάτο '
          + 'ριζόστρωμα για να ιδρώνει. Αποφύγετε ψεκασμό τις ζεστές ώρες.',
      },
    }];
  } catch (_e) { return []; }
}

// ── Η ΚΑΤΑΣΤΑΣΗ ΤΗΣ ΠΡΟΓΝΩΣΗΣ · ΠΑΝΤΑ, ΚΑΙ ΟΤΑΝ ΛΕΙΠΕΙ ─────────────────
// SAG-NOSILENT-01: «δεν προειδοποιώ» και «δεν έχω πρόγνωση» ΔΕΝ φαίνονται ίδια.
// ── T-FCWARN-01 (v50.113) · ΒΡΟΧΗ ΜΠΡΟΣΤΑ — ΠΛΑΙ ΣΤΑ ΛΙΤΡΑ, ΟΧΙ ΜΕΣΑ ΤΟΥΣ ──
// ΡΗΤΗ ΑΠΟΦΑΣΗ ΤΟΥ ΧΡΗΣΤΗ (6/9/2026): «Μόνο προειδοποίηση, χωρίς αλλαγή δόσης».
// Η δόση βγαίνει ΜΟΝΟ από μετρήσεις. Εδώ γράφεται ΞΕΧΩΡΙΣΤΟΣ δείκτης που
// στέκεται δίπλα της. Ο έλεγχος audit_forecast.js επιβάλλει ότι μέσα στις
// calculate_IrrigationVolume / calculate_FIR / calculate_InfectionHours δεν
// υπάρχει ΚΑΜΙΑ αναφορά στην πρόγνωση — αυτό ΔΕΝ αλλάζει.
const _SAG_RAIN_AHEAD_MM = 3;      // κάτω από αυτό δεν αξίζει ούτε αναφορά
function _sagRainAheadIndicators(fcs) {
  try {
    if (!fcs || !fcs.ok) return [];
    // T-COVERED-01: σε καλυμμένη καλλιέργεια η βροχή δεν φτάνει στο φυτό —
    // ο πυρήνας μηδενίζει ήδη κάθε rain_height. Θα ήταν αντίφαση να λέμε
    // «βροχή μπροστά, αναβάλετε το πότισμα» μέσα σε θερμοκήπιο.
    if (_SAG_COVERED_ACTIVE) return [];
    const R = Array.isArray(fcs.rain) ? fcs.rain : null;
    if (!R) return [];
    let sum = 0, firstAt = null, lastIdx = null;
    for (let i = fcs.i0; i < fcs.i1; i++) {
      const v = Number(R[i]);
      if (!Number.isFinite(v) || v <= 0) continue;
      sum += v;
      if (firstAt === null) firstAt = fcs.t[i];
      lastIdx = i;
    }
    if (!(sum >= _SAG_RAIN_AHEAD_MM) || firstAt === null) return [];
    const hrs = Math.max(1, Math.round((fcs.t[lastIdx] - fcs.t[fcs.i0]) / 3600000) + 1);
    const mm = sum.toLocaleString('el-GR', { maximumFractionDigits: 1 });
    return [{
      variable: 'rain_ahead',
      value: mm + ' mm βροχής μπροστά',
      metadata: {
        color: 'blue',
        text: 'Η πρόγνωση δίνει συνολικά ' + mm + ' mm βροχής μέσα στις επόμενες '
          + hrs + ' ώρες, με αρχή γύρω στις ' + _sagFcHour(firstAt, fcs.tz) + '. '
          + 'Η ΔΟΣΗ ΑΡΔΕΥΣΗΣ ΔΕΝ ΑΛΛΑΖΕΙ — υπολογίζεται ΜΟΝΟ από μετρήσεις, γιατί '
          + 'η βροχή μπορεί να μην πέσει. Αν θέλετε, αναβάλετε το πότισμα και '
          + 'δείτε αύριο τι έδειξε ο βροχόμετρος· το σύστημα θα το λάβει υπόψη '
          + 'μόνο του μόλις η βροχή ΜΕΤΡΗΘΕΙ.',
      },
    }];
  } catch (_e) { return []; }
}

// ── ΠΡΟΛΗΠΤΙΚΟ ΜΗΝΥΜΑ ΜΟΛΥΝΣΗΣ ────────────────────────────────────────────
// ΚΑΜΙΑ ΝΕΑ ΑΓΡΟΝΟΜΙΚΗ ΣΤΑΘΕΡΑ: τα κριτήρια είναι ΑΥΤΟΥΣΙΑ τα πεδία του
// PATHOGEN_PROFILE που ήδη χρησιμοποιεί η calculate_InfectionHours για τις
// ΜΕΤΡΗΜΕΝΕΣ ώρες — optimalTempRange, optimalHumidity.min, requiredDurationHrs.
// Η μόνη διαφορά είναι ότι εδώ εφαρμόζονται σε ΠΡΟΒΛΕΠΟΜΕΝΕΣ ώρες, και το
// κείμενο το λέει ΡΗΤΑ. Ο κίνδυνος (FIR) ΔΕΝ αγγίζεται.
const _SAG_INF_AHEAD_MAX_NAMES = 3;
function _sagInfectionAheadIndicators(fcs, parameters, pathogenProfile, already) {
  try {
    if (!fcs || !fcs.ok || !parameters) return [];
    // T-COVERED-01: μέσα σε θερμοκήπιο η υγρασία και η διαβροχή του φύλλου
    // ΔΕΝ είναι αυτές της πρόγνωσης. Καμία εικασία.
    if (_SAG_COVERED_ACTIVE) return [];
    const RH = Array.isArray(fcs.rh) ? fcs.rh : null;
    const R = Array.isArray(fcs.rain) ? fcs.rain : null;
    if (!RH && !R) return [];
    const match = (e) => e && e.cultivation_type_general === parameters.cultivation_type_general
      && e.cultivation_type === parameters.cultivation_type;
    const hits = [];
    let worstHrs = 0;
    for (const catKey of Object.keys(pathogenProfile || {})) {
      const cat = pathogenProfile[catKey] || {};
      for (const key of Object.keys(cat)) {
        const ph = cat[key];
        if (!ph || ph.type !== 'Infection_Triangle') continue;
        if (!Array.isArray(ph.crops) || !ph.crops.some(match)) continue;
        if (already && already.has(key)) continue;   // το ΜΕΤΡΗΜΕΝΟ το λέει ήδη
        const tmin = Number(ph.optimalTempRange && ph.optimalTempRange.min);
        const tmax = Number(ph.optimalTempRange && ph.optimalTempRange.max);
        const hmin = Number(ph.optimalHumidity && ph.optimalHumidity.min);
        const need = Number(ph.requiredDurationHrs);
        if (![tmin, tmax, hmin, need].every(Number.isFinite) || need <= 0) continue;
        // ΤΟ ΚΡΙΤΗΡΙΟ ΕΙΝΑΙ ΑΥΤΟΥΣΙΟ ΤΗΣ calculate_InfectionHours (γρ. ~7889):
        //   tempOk && humidityOk && wetOk && !rainInhibit
        // Η ΑΜΕΣΩΣ ΠΡΟΗΓΟΥΜΕΝΗ έκδοση έκανε OR υγρασίας/βροχής αντί για AND, και
        // αγνοούσε ΕΝΤΕΛΩΣ το rainInhibitsInfection — προειδοποιούσε για ωίδια
        // ΕΞΑΙΤΙΑΣ βροχής που τα ξεπλένει. Πέντε παθογόνα το δηλώνουν ρητά.
        // ΤΟ ΠΕΔΙΟ ΕΦΑΡΜΟΓΗΣ ΤΗΣ ΠΡΟΓΝΩΣΗΣ: ΜΟΝΟ όσα θέλουν ΔΙΑΒΡΟΧΗ ΦΥΛΛΟΥ.
        // Η προστιθέμενη αξία της πρόγνωσης είναι ΜΙΑ: «έρχεται υγρασία που δεν
        // υπάρχει ακόμη». Για τα ωίδια, που ΔΕΝ θέλουν διαβροχή (15 από τα 47),
        // η πρόγνωση δεν λέει τίποτα που να μην το λέει ήδη καλύτερα η
        // ΜΕΤΡΗΜΕΝΗ κάρτα — και τα κατώφλια τους (RH ≥ 40-50 %) ικανοποιούνται
        // σχεδόν κάθε νύχτα, οπότε η κάρτα έμενε ΜΟΝΙΜΑ πορτοκαλί σε 7 αγρούς
        // (κολοκύθι, αγγούρι, καρπούζι, πεπόνι). Μια προειδοποίηση που ανάβει
        // πάντα δεν είναι προειδοποίηση.
        if (ph.requiresLeafWetness === false) continue;
        const needsWet = true;
        const rainInh = (ph.rainInhibitsInfection === true);
        const rainThr = Number(ph.rainInhibitThresholdMm) || 2.5;
        let run = 0, best = 0;
        for (let i = fcs.i0; i < fcs.i1; i++) {
          const T = fcs.at(i);
          const h = RH ? Number(RH[i]) : NaN;
          const r = R ? Number(R[i]) : NaN;
          const rr = Number.isFinite(r) ? r : 0;
          const tempOk = (T !== null && T >= tmin && T <= tmax);
          const humOk = Number.isFinite(h) ? (h >= hmin) : (rr > 0);
          // Η πρόγνωση ΔΕΝ έχει αισθητήρα φύλλου. Ο μόνος τίμιος υποκατάστατος
          // της διαβροχής είναι βροχή ή κορεσμός — το ίδιο που χρησιμοποιεί
          // ήδη ο πυρήνας ως «δρόσος από αέρα» όταν λείπει ο αισθητήρας.
          const wetOk = needsWet ? (rr > 0 || (Number.isFinite(h) && h >= 90)) : true;
          const inhib = rainInh && rr > rainThr;
          if (tempOk && humOk && wetOk && !inhib) { run++; if (run > best) best = run; }
          else run = 0;
        }
        if (best >= need) {
          hits.push({ name: String(ph.name || key), hrs: best });
          if (best > worstHrs) worstHrs = best;
        }
      }
    }
    if (!hits.length) return [];
    hits.sort((a, b) => b.hrs - a.hrs);
    const names = hits.slice(0, _SAG_INF_AHEAD_MAX_NAMES).map(x => x.name).join(', ');
    const more = hits.length > _SAG_INF_AHEAD_MAX_NAMES
      ? (' και ' + (hits.length - _SAG_INF_AHEAD_MAX_NAMES) + ' ακόμη') : '';
    return [{
      variable: 'infection_ahead',
      value: hits.length + (hits.length === 1 ? ' παθογόνο ευνοείται' : ' παθογόνα ευνοούνται'),
      metadata: {
        color: 'orange',
        count: hits.length,
        text: 'ΠΡΟΓΝΩΣΗ, ΟΧΙ ΜΕΤΡΗΣΗ: οι επόμενες ώρες δίνουν έως ' + worstHrs
          + ' συνεχόμενες ώρες με υγρασία και θερμοκρασία μέσα στο εύρος μόλυνσης για: '
          + names + more + '. Ο ΚΙΝΔΥΝΟΣ ΣΤΙΣ ΚΑΡΤΕΣ ΔΕΝ ΑΛΛΑΖΕΙ — αυτός βγαίνει '
          + 'από μετρημένες ώρες υγρού φύλλου. Χρησιμοποιήστε το μόνο για να '
          + 'προλάβετε: προστατευτικός ψεκασμός θέλει να στεγνώσει πριν τη βροχή.',
      },
    }];
  } catch (_e) { return []; }
}

function _sagForecastStatusIndicators(fcs) {
  try {
    if (fcs && fcs.ok) {
      const hrs = fcs.i1 - fcs.i0;
      return [{ variable: 'forecast_status', value: 'Ενεργή',
        metadata: { color: 'green',
          text: 'Η πρόγνωση διαβάζεται από τον πυρήνα: ' + hrs + ' ώρες μπροστά'
            + (Number.isFinite(fcs.ageH) ? ' (ανανεώθηκε πριν ' + Math.round(fcs.ageH) + ' ώρες)' : '')
            + '. Χρησιμοποιείται ΜΟΝΟ για προειδοποιήσεις παγετού και καύσωνα — '
            + 'η δόση άρδευσης και ο κίνδυνος παθογόνων υπολογίζονται από ΜΕΤΡΗΣΕΙΣ.' } }];
    }
    return [{ variable: 'forecast_status', value: 'Μη διαθέσιμη',
      metadata: { color: 'grey',
        text: 'Δεν υπάρχει έγκυρη πρόγνωση για αυτόν τον αγρό: '
          + ((fcs && fcs.why) || 'άγνωστη αιτία')
          + '. Δεν βγαίνουν προειδοποιήσεις παγετού ή καύσωνα. Ελέγξτε ότι ο αγρός '
          + 'έχει ετικέτα «coordinates» και ότι τρέχει η analysis της πρόγνωσης.' } }];
  } catch (_e) { return []; }
}

// Υπολογίζεται ΜΙΑ φορά ανά αγρό και μένει στο `measurements.data`, όπως τα
// _sagAges και _sagFaults. Έτσι ο βρόχος καλλιεργειών δεν ξαναδιαβάζει τίποτα.
function _sagFcOf(measurements) {
  try {
    const d = measurements && measurements.data;
    if (!d) return null;
    if (d._sagFcSeries !== undefined) return d._sagFcSeries;
    const s = _sagForecastSeries(d._sagForecast, Date.now());
    d._sagFcSeries = s;
    return s;
  } catch (_e) { return null; }
}

function _sagDevInventoryIndicators(data) {
  try {
    const inv = (data && Array.isArray(data._sagDevInv)) ? data._sagDevInv : [];
    const rows = [];
    for (const d of inv) {
      if (!d) continue;
      const _id = String(d.i == null ? '' : d.i).trim();
      const _nm = String(d.n == null ? '' : d.n).trim();
      if (!_id || !_nm) continue;          // χωρίς id δεν ταιριάζει με το widget
      // Οι διαχωριστές ΔΕΝ επιτρέπεται να υπάρχουν μέσα στα πεδία.
      const _clean = (s) => String(s).replace(/[|:]/g, '-').slice(0, 48);
      rows.push(_id.slice(-6) + ':' + _clean(_nm) + ':'
        + _clean(String(d.t == null ? '' : d.t)));
    }
    if (!rows.length) return [];
    return [{
      variable: 'device_inventory',
      value: rows.length + (rows.length === 1 ? ' όργανο' : ' όργανα'),
      metadata: { color: 'grey', text: rows.join('|') },
    }];
  } catch (_e) { return []; }
}
