// Πηγή μετεωρολογικής αναφοράς (T-MET-REFERENCE-01)
// ── T-SOURCE-CARD-01 (v50.65) · ΠΟΙΟ ΟΡΓΑΝΟ ΟΔΗΓΕΙ ΚΑΘΕ ΔΕΙΚΤΗ ────────────
// Ερώτημα χρήστη 31/8: «αν ο αγρός έχει 2 αισθητήρες αέρα + σταθμό + αισθητήρα
// φύλλου, ΠΟΙΑ υγρασία χρησιμοποιεί το σύστημα;»
// Η απάντηση υπήρχε ήδη μέσα στον πυρήνα και δεν έβγαινε ποτέ: το `_sagSrc`
// κρατά, ανά μεταβλητή, ΠΟΙΕΣ συσκευές την τροφοδότησαν (T-MULTISENSOR-MERGE-01).
// Όταν είναι δύο ή περισσότερες, η τιμή είναι ο ΜΕΣΟΣ ΟΡΟΣ τους — όχι «η
// τελευταία που μίλησε». Εδώ γίνεται μία γραμμή που τη διαβάζει ο αγρότης.
// ΠΡΟΣΟΧΗ στο μέγεθος: τηλεγραφικό, μόνο τα μεγέθη που ΟΔΗΓΟΥΝ αποφάσεις.
const _SAG_SRC_ROWS = [
  ['Θερμ. αέρα',     ['air_temperature', 'temperature']],
  ['Υγρασία αέρα',   ['air_humidity', 'humidity']],
  ['Υγρασία φύλλου', ['leaf_moisture']],
  ['Θερμ. φύλλου',   ['leaf_temperature']],
  ['Υγρασία εδάφ.',  ['soil_moisture2', 'soil_moisture1', 'soil_moisture']],
  ['Θερμ. εδάφους',  ['soil_temperature2', 'soil_temperature1', 'soil_temperature', 'temp_soil']],
  ['Βροχή',          ['rain_height_daily', 'rain_height']],
  ['Άνεμος',         ['wind_speed_kmh']],
  // ── T-SRCROW-LIGHT-01 (v50.70 · τελικός έλεγχος 1/9) ──────────────────
  // ΕΥΡΗΜΑ: ο πίνακας «Ποια όργανα το τροφοδοτούν» ζητά γραμμή «Φως» για τις
  // Συνθήκες Ανάπτυξης (μηχανικά εξηγμένο από την calculate_BPI: dli_mol_m2_day,
  // light_intensity), αλλά εδώ ΔΕΝ υπήρχε — άρα ΚΑΘΕ αγρός, ακόμη και με υγιή
  // s2120, διάβαζε «δεν φτάνει μέτρηση σε αυτόν τον αγρό» για το φως. Ίδια
  // κατηγορία ψευδούς ισχυρισμού με το σφάλμα του ΚΕΚ.
  // ΠΡΟΣΟΧΗ: ΠΡΟΣΘΗΚΗ ΣΤΟ ΤΕΛΟΣ. Οι δείκτες 1-8 είναι συμβόλαιο με το widget —
  // παρεμβολή στη μέση θα διάβαζε λάθος κάθε αποθηκευμένο bundle.
  ['Φως',            ['light_intensity', 'dli_mol_m2_day', 'light_intensity_sum']],
];
function _sagSourceIndicators(data) {
  try {
    const src = (data && data._sagSrc) || {};
    if (!Object.keys(src).length) return [];
    // ── ΔΙΟΡΘΩΣΗ v50.66 · ΤΟ _sagSrc ΔΕΝ ΚΑΘΑΡΙΖΕΤΑΙ ΑΠΟ ΤΗΝ ΠΥΛΗ ──────────
    // Η πύλη ευλογοφάνειας αδειάζει το κανάλι (`data[key] = []`) αλλά ΑΦΗΝΕΙ
    // το `_sagSrc[key]` όπως ήταν. Χωρίς αυτόν τον έλεγχο, ο αγρός «Κρασαγάκης
    // Σπύρος» — όπου ΚΑΙ ΟΙ ΤΡΕΙΣ σόνδες δίνουν υγρασία 0 και απορρίπτονται —
    // θα διάβαζε «Υγρασία εδάφ.: μ.ό. 3 (…)» ΤΗΝ ΙΔΙΑ ΩΡΑ που η κάρτα δίπλα
    // λέει «Δεν υπάρχει έγκυρη μέτρηση υγρασίας εδάφους». Δύο αντιφατικές
    // προτάσεις στην ίδια οθόνη είναι χειρότερες από καμία πληροφορία.
    // ΚΑΝΟΝΑΣ: πηγή δηλώνεται ΜΟΝΟ για κανάλι που όντως έχει έγκυρη τιμή τώρα.
    // ΠΡΟΣΟΧΗ ΣΤΗ JAVASCRIPT: Number(null) === 0 και Number('') === 0 — ΚΑΙ ΤΑ ΔΥΟ
    // πεπερασμένα. Χωρίς ρητό φιλτράρισμα, ένα ΑΔΕΙΟ κανάλι θα δηλωνόταν ως
    // έγκυρη πηγή. Το ίδιο πάτημα έχει ξαναχτυπήσει στον πυρήνα (light_coverage,
    // daylight_complete) — εδώ το κόβουμε ΠΡΙΝ από κάθε μετατροπή.
    const _num = (x) => (x === null || x === undefined || x === '') ? NaN : Number(x);
    const _live = (k) => {
      const v = data ? data[k] : undefined;
      if (v === undefined || v === null) return false;
      if (Array.isArray(v)) {
        if (!v.length) return false;
        const f = v[0];
        return Number.isFinite(_num(f && typeof f === 'object' && 'value' in f ? f.value : f));
      }
      return Number.isFinite(_num(v && typeof v === 'object' && 'value' in v ? v.value : v));
    };
    const parts = [];
    // ── T-SRC-KEEP-01 (v50.69) · ΤΟ ΚΕΙΜΕΝΟ ΕΙΝΑΙ ΔΕΔΟΜΕΝΑ ────────────────
    // Μετρημένο 1/9 με τον ΠΡΑΓΜΑΤΙΚΟ συμπιεστή σε bundle ΚΕΚ (9.188 B):
    //   πρόζα με ονόματα        183 χαρ. -> +116 B
    //   πρόζα με κωδικούς       130 χαρ. -> +112 B
    //   κωδικοί + δείκτες        43 χαρ. ->  +44 B  ← αυτό
    // Πληρώνει ΜΟΝΟ η αφαίρεση ΜΟΝΑΔΙΚΗΣ πληροφορίας: τα ονόματα συσκευών
    // τα ταιριάζει ήδη το deflate με το device_inventory· αυτό που κοστίζει
    // είναι οι ελληνικές ετικέτες — και αυτές ζουν ΗΔΗ μέσα στο widget.
    // Μορφή: <δείκτης[,δείκτης]>:<κωδικός[,κωδικός]>|... · '!' = καμία έγκυρη.
    const _byName = {};
    try { for (const _d of (Array.isArray(data && data._sagDevInv) ? data._sagDevInv : [])) {
      const _i = String(_d && _d.i != null ? _d.i : '').trim();
      const _n = String(_d && _d.n != null ? _d.n : '').trim();
      if (_i && _n) _byName[_n] = _i.slice(-6);
    } } catch (_eBN) {}
    const _code = (nm) => {
      const _c = _byName[nm];
      return _c ? _c : String(nm).replace(/[|:,]/g, '-').slice(0, 40);
    };
    let _rowIdx = 0;
    for (const [label, keys] of _SAG_SRC_ROWS) {
      _rowIdx++;
      let used = null, usedKey = null, _hadDead = false;
      for (const k of keys) {
        const s = src[k];
        if (!Array.isArray(s) || !s.length) continue;
        if (!_live(k)) { _hadDead = true; continue; }   // απορρίφθηκε/άδειασε
        used = s; usedKey = k; break;
      }
      if (!used) {
        // Το όργανο μίλησε αλλά ΚΑΜΙΑ τιμή δεν πέρασε: αυτό ΕΙΝΑΙ η πληροφορία.
        if (_hadDead) parts.push({ labels: [label], who: 'καμία έγκυρη μέτρηση',
          idx: [_rowIdx], dev: null });
        continue;
      }
      const uniq = [];
      for (const d of used) if (d && uniq.indexOf(d) < 0) uniq.push(d);
      if (!uniq.length) continue;
      const _who = uniq.length === 1 ? uniq[0]
        : ('μ.ό. ' + uniq.length + ' (' + uniq.join(', ') + ')');
      // Τα ίδια όργανα δίνουν συνήθως θερμοκρασία ΚΑΙ υγρασία του ίδιου μέσου.
      // Χωρίς συγχώνευση το κείμενο διπλασιάζεται σε bytes χωρίς νέα πληροφορία.
      const _last = parts[parts.length - 1];
      if (_last && _last.who === _who) { _last.labels.push(label); _last.idx.push(_rowIdx); }
      else parts.push({ labels: [label], who: _who, idx: [_rowIdx], dev: uniq });
    }
    if (!parts.length) return [];
    const _multi = parts.filter(x => x.who.indexOf('μ.ό.') >= 0).length;
    return [{
      variable: 'measurement_sources',
      value: _multi ? (_multi === 1 ? '1 μέγεθος από μέσο όρο' : _multi + ' μεγέθη από μέσο όρο')
        : 'Ένα όργανο ανά μέγεθος',
      metadata: { color: 'grey',
        // T-SRC-KEEP-01: συμπαγής μορφή δεδομένων — το widget την ξεδιπλώνει
        // με τον δικό του πίνακα ετικετών και το device_inventory.
        text: parts.map(x => x.idx.join(',') + ':'
          + (x.dev && x.dev.length ? x.dev.map(_code).join(',') : '!')).join('|') },
    }];
  } catch (_e) { return []; }
}

function _sagMetSourceIndicators(data) {
  const s = data && data._sagMetSource;
  if (!s || s === 'none') return [];
  return [{ variable: 'met_reference_source',
    value: s === 'station' ? 'Μετεωρολογικός σταθμός' : 'Αισθητήρας κόμης',
    metadata: { color: s === 'station' ? 'green' : 'orange',
      text: s === 'station'
        ? 'Οι θερμοκρασίες αναφοράς προέρχονται από τον μετεωρολογικό σταθμό.'
        : 'Χωρίς μετεωρολογικό σταθμό: οι θερμοκρασίες έρχονται από τον αισθητήρα '
          + 'κόμης. Έχει ασπίδα ακτινοβολίας, αλλά μετράει μέσα στο φύλλωμα και όχι '
          + 'στα 2 m του προτύπου: στους αγρούς με ΚΑΙ τα δύο όργανα έδωσε ψηλότερο '
          + 'μέγιστο, άρα η δόση μπορεί να υπερεκτιμάται.' } }];
}
