// T-CONFIG-REPAIR-01 (20/8/2026) — ΕΛΕΓΧΟΣ ΚΑΙ ΕΠΙΔΙΟΡΘΩΣΗ CONFIGURATION
// ----------------------------------------------------------------------------
// ΓΙΑΤΙ ΕΙΝΑΙ ΕΔΩ: ο χειριστής ΔΕΝ μπορεί να δημιουργήσει νέο Analysis στην
// TagoIO. Κάθε εργαλείο συντήρησης πρέπει να ζει μέσα στον πυρήνα, πίσω από
// σημαία — όπως και το T-DIAG-FIELDFORM-01.
//
// ΤΡΕΙΣ ΒΑΘΜΙΔΕΣ ΑΣΦΑΛΕΙΑΣ:
//   SAG_FIX_CONFIG      = false → ΜΗΔΕΝ κόστος, δεν τρέχει καθόλου.
//   SAG_FIX_CONFIG      = true  → ΜΟΝΟ ΔΙΑΒΑΖΕΙ και τυπώνει λίστα εργασίας.
//   SAG_FIX_CONFIG_WRITE= true  → ΚΑΙ γράφει, αλλά ΜΟΝΟ ό,τι τεκμηριώνεται από
//                                 δεδομένα που ΗΔΗ υπάρχουν στη συσκευή.
//
// ΤΙ ΔΕΝ ΚΑΝΕΙ ΠΟΤΕ: δεν εφευρίσκει τιμές, δεν σβήνει tag, δεν πειράζει τιμή
// που ήδη υπάρχει, δεν αγγίζει άλλο tag εκτός από το «configuration».
//
// ΣΗΜΕΙΩΣΗ: το latitude διορθώνεται ΗΔΗ στη μνήμη σε κάθε εκτέλεση από το
// T-LATLON-FROMTAG-01. Η εγγραφή εδώ είναι απλώς η μονιμοποίησή του — δεν
// είναι απαραίτητη για να δουλέψει ο πυρήνας.
const SAG_FIX_CONFIG = false;         // ολοκληρώθηκε 20/8: 28 αγροί επιδιορθώθηκαν
const SAG_FIX_CONFIG_WRITE = false;   // ← true ΜΟΝΟ μαζί με SAG_FIX_CONFIG, αφού δεις το log

// Σημεία επίδειξης/κτηριακά — δεν είναι παραγωγικοί αγροί, δεν τους κυνηγάμε.
const _SAG_DEMO_HINTS = ['Γκαζόν', 'Κτήριο', 'Κτίριο', 'Παρτέρι', 'Reception',
  'ΔΗΜΑΡΧΕΙΟ', 'Ηλεκτροβάνα', 'Βραχόκηπος', 'Υπόσκαφο', 'CyRIC', 'Ντομάτες Dragino'];

function _sagCfgYearOk(v) {
  const n = Number(String(v).slice(0, 4));
  return Number.isFinite(n) && n > 1900 && n <= new Date().getFullYear();
}

async function _sagRepairConfig(account) {
  const L = (s) => { try { console.log(s); } catch (_e) {} };
  L('');
  L('╔══════════════════════════════════════════════════════════════════════╗');
  L('║  T-CONFIG-REPAIR-01 · ' + _sagDiagPad(SAG_FIX_CONFIG_WRITE
      ? 'ΠΡΑΓΜΑΤΙΚΗ ΕΓΓΡΑΦΗ' : 'ΜΟΝΟ ΑΝΑΓΝΩΣΗ — καμία εγγραφή', 46) + '║');
  L('╚══════════════════════════════════════════════════════════════════════╝');

  let all = [], page = 1;
  while (page <= 20) {
    const b = await Resources.devices.list({
      page, amount: 100, fields: ['id', 'name', 'tags'],
      filter: { tags: [{ key: 'isField', value: 'yes' }] },
    });
    if (!Array.isArray(b) || !b.length) break;
    all = all.concat(b); page += 1;
  }

  const okList = [], autoList = [], humanList = [], demoList = [], noCfgList = [];

  for (const d of all) {
    const tags = d.tags || [];
    const label = tags.filter(t => t.key === 'name').map(t => t.value)[0] || d.name;
    // Η ΤΑΥΤΟΤΗΤΑ είναι το id, όχι το όνομα. Πέντε ζευγάρια αγρών μοιράζονται
    // ονόματα, και σε ένα από αυτά το όνομα της συσκευής είναι ΤΕΛΕΙΩΣ άλλο
    // («Σκοτίνα Πάνω» → Field_Όρμα). Χωρίς id η λίστα δεν είναι ενεργήσιμη.
    const ident = { label, dev: d.name, id: d.id };
    const isDemo = _SAG_DEMO_HINTS.some(h => String(label).indexOf(h) >= 0);

    const cfgTag = tags.find(t => t.key === 'configuration');
    if (!cfgTag) { (isDemo ? demoList : noCfgList).push(label); continue; }

    let cfg = null;
    try { cfg = JSON.parse(String(cfgTag.value)); }
    catch (e) { humanList.push({ ident: { label, dev: d.name, id: d.id }, need: ['ΑΚΥΡΟ JSON'] }); continue; }

    const missing = [];
    if (!(Number(cfg.area) > 0)) missing.push('area');
    if (!Number.isFinite(Number(cfg.latitude))) missing.push('latitude');
    const cpy = (Array.isArray(cfg.crops) && cfg.crops[0]) ? cfg.crops[0].plantation_year : undefined;
    if (!(_sagCfgYearOk(cfg.plantation_year) || _sagCfgYearOk(cpy))) missing.push('plantation_year');
    if (!(Array.isArray(cfg.crops) && cfg.crops.length)) missing.push('crops');
    if (!missing.length) { okList.push(label); continue; }

    // ── Τι τεκμηριώνεται από δεδομένα που ΥΠΑΡΧΟΥΝ ήδη στη συσκευή ────────
    const fixes = [];
    if (missing.indexOf('latitude') >= 0) {
      const co = tags.filter(t => t.key === 'coordinates').map(t => t.value)[0];
      if (typeof co === 'string') {
        const pr = co.split(',');
        const la = Number(String(pr[0]).trim());
        const lo = Number(String(pr[1]).trim());
        if (Number.isFinite(la) && la >= -90 && la <= 90) {
          fixes.push(['latitude', la]);
          if (Number.isFinite(lo) && !Number.isFinite(Number(cfg.longitude))) fixes.push(['longitude', lo]);
        }
      }
    }
    const stillHuman = missing.filter(m => !fixes.some(f => f[0] === m));

    L('');
    L('── ' + label + '  [' + d.id + ']');
    L('   λείπουν: ' + missing.join(', '));
    for (const f of fixes) L('   ✎ ΑΥΤΟΜΑΤΑ  ' + _sagDiagPad(f[0], 12) + '= ' + f[1] + '   (πηγή: tag «coordinates»)');
    if (stillHuman.length) {
      L('   ✋ ΘΕΛΕΙ ΑΝΘΡΩΠΟ: ' + stillHuman.join(', '));
      humanList.push({ ident, need: stillHuman });
    }

    if (fixes.length) {
      for (const f of fixes) cfg[f[0]] = f[1];
      const after = JSON.stringify(cfg);
      L('   configuration: ' + String(cfgTag.value).length + ' → ' + after.length + ' χαρακτήρες');
      if (!SAG_FIX_CONFIG_WRITE) {
        L('   (ΜΟΝΟ ΑΝΑΓΝΩΣΗ — δεν γράφτηκε τίποτα)');
        autoList.push(label);
      } else {
        try {
          const newTags = tags.filter(t => t.key !== 'configuration')
            .concat([{ key: 'configuration', value: after }]);
          await account.devices.edit(d.id, { tags: newTags });
          L('   ✓ ΓΡΑΦΤΗΚΕ');
          autoList.push(label);
        } catch (e) {
          L('   ✗ Η ΕΓΓΡΑΦΗ ΑΠΕΤΥΧΕ: ' + (e && e.message));
          L('     → ΑΥΤΟ ΤΟ ΣΦΑΛΜΑ ΕΙΝΑΙ ΚΑΙ Η ΑΠΑΝΤΗΣΗ για το γιατί σιωπά η φόρμα.');
        }
      }
    }
  }

  L('');
  L('═══ ΣΥΝΟΨΗ ═══');
  L('  ΕΝΤΑΞΕΙ                      : ' + okList.length);
  L('  ΕΠΙΔΙΟΡΘΩΣΙΜΟΙ ΑΥΤΟΜΑΤΑ      : ' + autoList.length
    + (SAG_FIX_CONFIG_WRITE ? ' (γράφτηκαν)' : ' (θα γράφονταν με SAG_FIX_CONFIG_WRITE=true)'));
  L('  ΘΕΛΟΥΝ ΑΝΘΡΩΠΟ               : ' + humanList.length);
  L('  ΑΓΡΟΙ ΧΩΡΙΣ ΚΑΜΙΑ ΡΥΘΜΙΣΗ    : ' + noCfgList.length + '  — ΔΕΝ υπολογίζεται τίποτα γι αυτούς');
  L('  Σημεία επίδειξης χωρίς ρύθμιση: ' + demoList.length + '  — αγνοούνται σκόπιμα');
  if (noCfgList.length) {
    L('');
    for (const n of noCfgList) L('    · ' + n);
  }
  L('');
  L('═══ ΛΙΣΤΑ ΕΡΓΑΣΙΑΣ — δώσ την στον γεωπόνο ═══');
  if (!humanList.length) L('  καμία ✓');
  else {
    // Ταξινόμηση ώστε οι ομώνυμοι αγροί να είναι δίπλα-δίπλα και να φαίνεται
    // αμέσως ότι πρόκειται για ΔΙΑΦΟΡΕΤΙΚΑ χωράφια.
    const _dupLabels = humanList.map(w => w.ident.label)
      .filter((v, i, a) => a.indexOf(v) !== i);
    humanList.sort((a, b) => (a.ident.label < b.ident.label ? -1 : a.ident.label > b.ident.label ? 1 : 0));
    // ΔΥΟ ΚΑΤΗΓΟΡΙΕΣ, ΓΙΑΤΙ ΔΕΝ ΕΙΝΑΙ ΙΔΙΑΣ ΒΑΡΥΤΗΤΑΣ:
    //   ΕΠΕΙΓΟΝ  — λείπει `area` ή `crops`: ο αγρός ΔΕΝ υπολογίζει άρδευση
    //              καθόλου (στα logs: «Config error: area='null'»).
    //   ΔΕΥΤΕΡΕΥΟΝ — λείπει μόνο `plantation_year`: ο αγρός δουλεύει, αλλά με
    //              προεπιλεγμένη ηλικία 4 ετών, που αλλοιώνει τον συντελεστή
    //              καλλιέργειας και άρα τη δόση.
    const _urgent = (w) => w.need.some(k => k === 'area' || k === 'crops' || k === 'ΑΚΥΡΟ JSON');
    const _hdr = () => L('  ' + _sagDiagCol('ΑΓΡΟΣ', 28) + _sagDiagCol('ΣΥΣΚΕΥΗ', 30)
        + _sagDiagCol('ID', 26) + 'ΤΙ ΛΕΙΠΕΙ');
    const _row = (w) => L('  '
        + _sagDiagCol(w.ident.label + (_dupLabels.indexOf(w.ident.label) >= 0 ? ' ⚠' : ''), 28)
        + _sagDiagCol(w.ident.dev, 30) + _sagDiagCol(w.ident.id, 26) + w.need.join(', '));
    const _u = humanList.filter(_urgent), _s = humanList.filter(w => !_urgent(w));
    if (_u.length) {
      L('');
      L('  ▓▓ ΕΠΕΙΓΟΝ — ' + _u.length + (_u.length === 1 ? ' αγρός ΔΕΝ ΥΠΟΛΟΓΙΖΕΙ ΑΡΔΕΥΣΗ'
        : ' αγροί ΔΕΝ ΥΠΟΛΟΓΙΖΟΥΝ ΑΡΔΕΥΣΗ') + ' ▓▓');
      _hdr();
      for (const w of _u) _row(w);
    }
    if (_s.length) {
      L('');
      L('  ░░ ΔΕΥΤΕΡΕΥΟΝ — ' + _s.length + ' αγροί λειτουργούν, αλλά με προεπιλεγμένη');
      L('     ηλικία 4 ετών· ο συντελεστής καλλιέργειας και άρα η δόση αλλοιώνονται ░░');
      _hdr();
      for (const w of _s) _row(w);
    }
    if (_dupLabels.length) {
      L('');
      L('  ⚠ ΠΡΟΣΟΧΗ: τα σημειωμένα ονόματα ανήκουν σε ΠΕΡΙΣΣΟΤΕΡΟΥΣ ΑΠΟ ΕΝΑΝ αγρό.');
      L('    Ταυτοποίησέ τους από το ID, ΟΧΙ από το όνομα — σε έναν από αυτούς το');
      L('    όνομα της συσκευής είναι εντελώς διαφορετικό από την ετικέτα του αγρού.');
    }
    L('');
    L('  area            = εμβαδόν σε m² (ΟΧΙ στρέμματα, ΟΧΙ τελεία χιλιάδων)');
    L('  plantation_year = έτος φύτευσης, π.χ. 2015');
    L('  crops           = τουλάχιστον μία καλλιέργεια');
  }
  L('');
  L('═══ ΤΕΛΟΣ T-CONFIG-REPAIR-01 ═══');
  L('');
}
