// T-QUARANTINE-01 (v50.50 · Σ2): πάνω από τόσες ώρες σιωπής (last_input),
// οι αναγνώσεις δεδομένων της συσκευής παραλείπονται. Η επάνοδος είναι
// αυτόματη: το last_input φρεσκάρει με την πρώτη εκπομπή (νέα μπαταρία) και
// το ΕΠΟΜΕΝΟ tick διαβάζει ξανά κανονικά — καμία μαύρη λίστα, κανένα κουμπί.
const _SAG_QUARANTINE_H = 7 * 24;
// ── T-OPS-ROUTE-01 (v50.59) · ΠΟΥ ΠΑΝΕ ΟΙ ΛΕΙΤΟΥΡΓΙΚΕΣ ΑΝΑΦΟΡΕΣ ─────────
// Αφορούν ΕΜΑΣ (τεχνικό/διαχειριστή), ΠΟΤΕ τον αγρότη. Email πάντα (ρητοί
// παραλήπτες)· Notification μόνο αν ζητηθεί ρητά με OPS_NOTIFY=yes.
const _SAG_OPS_EMAIL_DEFAULT = 'sales@macc.gr';
function _sagOpsRecipients(env) {
  const _pick = (k) => { try { const e = (env || []).find(x => x && x.key === k);
    return e && e.value ? String(e.value) : ''; } catch (_e) { return ''; } };
  const _raw = _pick('OPS_EMAIL') || _pick('ADMIN_ALERT_EMAIL') || _SAG_OPS_EMAIL_DEFAULT;
  const _list = _raw.split(/[,;\s]+/).map(s => s.trim())
    .filter(s => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s));
  const _uniq = [];
  for (const _a of _list) if (_uniq.indexOf(_a) < 0) _uniq.push(_a);
  const _nf = _pick('OPS_NOTIFY').toLowerCase();
  return { to: _uniq, notify: ['yes', 'true', '1', 'ναι'].indexOf(_nf) >= 0 };
}

// Στέλνει και επιστρέφει τι έγινε. ΠΟΤΕ δεν ρίχνει τον κύκλο.
async function _sagOpsSend(env, token, title, message) {
  const _r = _sagOpsRecipients(env);
  const _done = { mail: 0, notify: 0, err: [] };
  for (const _to of _r.to) {
    try {
      await new Services({ token }).email.send({ to: _to, subject: title, message });
      _done.mail++;
    } catch (_eM) { _done.err.push('email ' + _to + ': ' + (_eM && _eM.message)); }
  }
  if (_r.notify) {
    try {
      await new Services({ token }).Notification.send({ title, message });
      _done.notify = 1;
    } catch (_eN) { _done.err.push('notification: ' + (_eN && _eN.message)); }
  }
  return _done;
}

// ── T-TECH-REPORT-01 (v50.58) · ΤΙ ΧΑΝΕΤΑΙ ΟΤΑΝ ΠΕΘΑΝΕΙ ΤΟ ΟΡΓΑΝΟ ────────
